INSERT INTO festival (id, name, en_name, festival_date, year, regions, intro, advice) VALUES
(1,'元旦','New Year''s Day','2026-01-01',2026,'NA,EU,SEA,LATAM','公历1月1日，全球多数地区的公共假日。庆祝从12月31日新年前夜开始：家庭用金色与黑色气球拱门、拉旗、LED灯串布置客厅，年轻人参加倒计时派对，佩戴新年眼镜与派对帽，午夜举杯后抛洒彩屑。1月1日多以家庭早午餐、观看新年游行和橄榄球碗赛为主。','12月初即上架派对装饰与拍照道具；印有具体年份的眼镜、数字气球须在节前清完库存，避免跨年滞销，可与圣诞装饰做组合套装提客单。'),
(2,'元旦','New Year''s Day','2027-01-01',2027,'NA,EU,SEA,LATAM','公历1月1日，全球多数地区的公共假日。庆祝从12月31日新年前夜开始：家庭用金色与黑色气球拱门、拉旗、LED灯串布置客厅，年轻人参加倒计时派对，佩戴新年眼镜与派对帽，午夜举杯后抛洒彩屑。1月1日多以家庭早午餐、观看新年游行和橄榄球碗赛为主。','12月初即上架派对装饰与拍照道具；印有具体年份的眼镜、数字气球须在节前清完库存，避免跨年滞销，可与圣诞装饰做组合套装提客单。'),
(3,'三王节','Día de Reyes / Three Kings Day','2026-01-06',2026,'LATAM,EU','1月6日主显节，西班牙与拉美大部分地区的公共假日。节前夜儿童把鞋子放在门口或窗下，等待三位国王骑骆驼送来礼物；6日全家分食圆形国王面包（Rosca de Reyes），面包内藏小玩偶，吃到者要主持2月2日圣烛节聚会。家中与教堂布置三王、骆驼与伯利恒之星主题装饰。','西语市场圣诞季最后一个礼品窗口，12月至1月初集中出单；皇冠、骆驼与伯利恒之星为差异化品类，国王面包配件（小塑料玩偶、包装盒）复购稳定。'),
(4,'三王节','Día de Reyes / Three Kings Day','2027-01-06',2027,'LATAM,EU','1月6日主显节，西班牙与拉美大部分地区的公共假日。节前夜儿童把鞋子放在门口或窗下，等待三位国王骑骆驼送来礼物；6日全家分食圆形国王面包（Rosca de Reyes），面包内藏小玩偶，吃到者要主持2月2日圣烛节聚会。家中与教堂布置三王、骆驼与伯利恒之星主题装饰。','西语市场圣诞季最后一个礼品窗口，12月至1月初集中出单；皇冠、骆驼与伯利恒之星为差异化品类，国王面包配件（小塑料玩偶、包装盒）复购稳定。'),
(5,'马丁·路德·金纪念日','Martin Luther King Jr. Day','2026-01-19',2026,'NA','美国联邦假日，每年1月第三个星期一，纪念民权运动领袖马丁·路德·金。当天学校、教堂与社区中心举行演讲、朗诵与志愿服务，教室布置“我有一个梦想”主题墙报、和平鸽手工与多元文化横幅，各地也举办纪念游行与免费社区餐会。','节日客单以学校教室装饰为主，1月上旬是采购高峰；多元文化、平权主题物料可与2月黑人历史月合并备货，拉长销售周期。'),
(6,'马丁·路德·金纪念日','Martin Luther King Jr. Day','2027-01-18',2027,'NA','美国联邦假日，每年1月第三个星期一，纪念民权运动领袖马丁·路德·金。当天学校、教堂与社区中心举行演讲、朗诵与志愿服务，教室布置“我有一个梦想”主题墙报、和平鸽手工与多元文化横幅，各地也举办纪念游行与免费社区餐会。','节日客单以学校教室装饰为主，1月上旬是采购高峰；多元文化、平权主题物料可与2月黑人历史月合并备货，拉长销售周期。'),
(7,'越南春节','Tết Nguyên Đán / Lunar New Year','2026-02-17',2026,'SEA','越南最重要的农历新年（2026年为2月17日），除夕至初五全国放假。节前家家户户大扫除、采购桃花枝（北部）与黄梅（南部）、摆放年橘盆景，大门贴红色春联与福字；除夕守岁、初一拜年发利是，供桌摆五果盘与粽子，街头挂满红灯笼与节日旗。','红色年俗商品节前两周集中爆发，利是封、春联为走量爆款；桃花、年橘等大件适合本地海外仓，跨境卖家主推轻量化装饰与利是封。'),
(8,'越南春节','Tết Nguyên Đán / Lunar New Year','2027-02-06',2027,'SEA','越南最重要的农历新年（2026年为2月17日），除夕至初五全国放假。节前家家户户大扫除、采购桃花枝（北部）与黄梅（南部）、摆放年橘盆景，大门贴红色春联与福字；除夕守岁、初一拜年发利是，供桌摆五果盘与粽子，街头挂满红灯笼与节日旗。','红色年俗商品节前两周集中爆发，利是封、春联为走量爆款；桃花、年橘等大件适合本地海外仓，跨境卖家主推轻量化装饰与利是封。'),
(9,'狂欢节（马迪格拉斯）','Mardi Gras / Carnival','2026-02-17',2026,'EU','圣灰星期三前的星期二（2026年为2月17日），欧洲狂欢季的收官日，新奥尔良有持续两周的游行季。街道与派对现场以紫金绿三色装饰，参加者佩戴面具、抛接珠链、挥舞羽毛披肩；花车游行沿途举办街区派对，国王饼是节令食品。','装扮类商品节前两周集中爆发，面具与珠链是刚需消耗品，可多件装出售；紫金绿三色套装辨识度高，适合做组合包提客单。'),
(10,'狂欢节（马迪格拉斯）','Mardi Gras / Carnival','2027-02-09',2027,'EU','圣灰星期三前的星期二（2026年为2月17日），欧洲狂欢季的收官日，新奥尔良有持续两周的游行季。街道与派对现场以紫金绿三色装饰，参加者佩戴面具、抛接珠链、挥舞羽毛披肩；花车游行沿途举办街区派对，国王饼是节令食品。','装扮类商品节前两周集中爆发，面具与珠链是刚需消耗品，可多件装出售；紫金绿三色套装辨识度高，适合做组合包提客单。'),
(11,'巴西狂欢节','Rio Carnival','2026-02-13',2026,'LATAM','全球规模最大的狂欢节（2026年2月13日起，圣灰星期三前），里约桑巴大道举行通宵桑巴校队游行，全城举办街头Bloco街区派对。参与者身着羽毛头饰、亮片服饰，抛洒五彩纸屑，海岸城市同时结合沙滩派对，庆典持续约一周。','羽毛头饰与桑巴服饰客单价高、重量轻，适合提前45天海运；亮片短裤、身体闪粉等配件可做多款组合，2月初为流量高峰。'),
(12,'巴西狂欢节','Rio Carnival','2027-02-05',2027,'LATAM','全球规模最大的狂欢节（2026年2月13日起，圣灰星期三前），里约桑巴大道举行通宵桑巴校队游行，全城举办街头Bloco街区派对。参与者身着羽毛头饰、亮片服饰，抛洒五彩纸屑，海岸城市同时结合沙滩派对，庆典持续约一周。','羽毛头饰与桑巴服饰客单价高、重量轻，适合提前45天海运；亮片短裤、身体闪粉等配件可做多款组合，2月初为流量高峰。'),
(13,'情人节','Valentine''s Day','2026-02-14',2026,'NA,EU,SEA','2月14日，北美与欧洲的浪漫节日。2月上旬餐厅与酒店即被订满，家庭与求婚现场以红粉气球、爱心拉旗、仿真玫瑰花瓣布置餐桌与卧室；当天互赠鲜花、珠宝、巧克力与卡片，晚间多为烛光晚餐或周末短途旅行。','提前一个月上架，1月下旬进入流量高峰；永生花、女士饰品为主推高客单，气球与派对装饰走量，注意贺卡文案无拼写错误以提高转化。'),
(14,'情人节','Valentine''s Day','2027-02-14',2027,'NA,EU,SEA','2月14日，北美与欧洲的浪漫节日。2月上旬餐厅与酒店即被订满，家庭与求婚现场以红粉气球、爱心拉旗、仿真玫瑰花瓣布置餐桌与卧室；当天互赠鲜花、珠宝、巧克力与卡片，晚间多为烛光晚餐或周末短途旅行。','提前一个月上架，1月下旬进入流量高峰；永生花、女士饰品为主推高客单，气球与派对装饰走量，注意贺卡文案无拼写错误以提高转化。'),
(15,'总统日','Presidents'' Day','2026-02-16',2026,'NA','美国联邦假日，每年2月第三个星期一，纪念乔治·华盛顿等历任总统。商场借长周末举办大促，学校教室布置总统主题墙报与认知卡片，红白蓝爱国装饰出现在社区活动中心，部分城市举办历史重演与纪念仪式。','红白蓝主题装饰可与阵亡将士纪念日、独立日共用一套供应链；电商平台普遍有长周末促销，2月上旬备好库存蹭平台流量。'),
(16,'总统日','Presidents'' Day','2027-02-15',2027,'NA','美国联邦假日，每年2月第三个星期一，纪念乔治·华盛顿等历任总统。商场借长周末举办大促，学校教室布置总统主题墙报与认知卡片，红白蓝爱国装饰出现在社区活动中心，部分城市举办历史重演与纪念仪式。','红白蓝主题装饰可与阵亡将士纪念日、独立日共用一套供应链；电商平台普遍有长周末促销，2月上旬备好库存蹭平台流量。'),
(17,'斋月开始','Ramadan Begins','2026-02-18',2026,'ME','伊斯兰历九月斋月（2026年约2月18日开始），持续约30天。穆斯林白天斋戒、日落后开斋聚餐，家中以新月星星造型灯笼、串灯布置客厅与餐桌，门挂斋月标识；夜晚清真寺与商场灯火通明，家庭备椰枣、点心招待访客，最后十天还有夜间礼拜与寻找盖德尔夜的活动。','斋月灯饰与家居装饰在中东爆发式增长，灯笼（Fanous）为标志性爆款；须提前45天备货，倒计时日历、桌旗等新品类竞争小、毛利高。'),
(18,'斋月开始','Ramadan Begins','2027-02-07',2027,'ME','伊斯兰历九月斋月（2026年约2月18日开始），持续约30天。穆斯林白天斋戒、日落后开斋聚餐，家中以新月星星造型灯笼、串灯布置客厅与餐桌，门挂斋月标识；夜晚清真寺与商场灯火通明，家庭备椰枣、点心招待访客，最后十天还有夜间礼拜与寻找盖德尔夜的活动。','斋月灯饰与家居装饰在中东爆发式增长，灯笼（Fanous）为标志性爆款；须提前45天备货，倒计时日历、桌旗等新品类竞争小、毛利高。'),
(19,'国际妇女节','International Women''s Day','2026-03-08',2026,'EU,ME','3月8日联合国纪念日，在东欧、中亚与俄语区是法定假日。当天男性向母亲、妻子与同事赠送郁金香、贺卡与礼盒，公司组织庆祝活动并发放礼品，餐厅推出节日套餐；街头花市从早晨开始排队，晚间多为家庭聚餐或演出。','郁金香、贺卡与礼盒是主流，3月初进入高峰；中亚与俄罗斯市场客单可做高，丝巾、香水等实用礼品优于纯装饰。'),
(20,'国际妇女节','International Women''s Day','2027-03-08',2027,'EU,ME','3月8日联合国纪念日，在东欧、中亚与俄语区是法定假日。当天男性向母亲、妻子与同事赠送郁金香、贺卡与礼盒，公司组织庆祝活动并发放礼品，餐厅推出节日套餐；街头花市从早晨开始排队，晚间多为家庭聚餐或演出。','郁金香、贺卡与礼盒是主流，3月初进入高峰；中亚与俄罗斯市场客单可做高，丝巾、香水等实用礼品优于纯装饰。'),
(21,'圣帕特里克节','St. Patrick''s Day','2026-03-17',2026,'NA','3月17日爱尔兰传统宗教节日，在美国已演变为全民绿色狂欢。纽约、芝加哥等城市举行盛大游行，酒吧与派对现场以绿色三叶草装饰，参加者全身绿色装扮、佩戴珠链、饮用绿色啤酒；当天还有教堂礼拜与传统音乐节。','绿色装扮是绝对主题，客单低但转化高，适合眼镜、袜子、项链等多件组合套装；3月上旬完成上架，酒吧周边用品需求集中。'),
(22,'圣帕特里克节','St. Patrick''s Day','2027-03-17',2027,'NA','3月17日爱尔兰传统宗教节日，在美国已演变为全民绿色狂欢。纽约、芝加哥等城市举行盛大游行，酒吧与派对现场以绿色三叶草装饰，参加者全身绿色装扮、佩戴珠链、饮用绿色啤酒；当天还有教堂礼拜与传统音乐节。','绿色装扮是绝对主题，客单低但转化高，适合眼镜、袜子、项链等多件组合套装；3月上旬完成上架，酒吧周边用品需求集中。'),
(23,'英国母亲节','Mothering Sunday','2026-03-15',2026,'EU','英国母亲节为四旬期第四个星期日（2026年3月15日）。子女带母亲享用英式下午茶、赠送鲜花与贺卡，家中布置春季花卉；当天教堂举行探访母堂的传统礼拜，餐厅与茶室全部订满，商场推出下午茶礼盒与香薰礼品。','注意与5月美国母亲节是两个日期，英国站需提前一个月单独备货；茶具、香薰蜡烛与鲜花包装为主推品类。'),
(24,'英国母亲节','Mothering Sunday','2027-03-07',2027,'EU','英国母亲节为四旬期第四个星期日（2026年3月15日）。子女带母亲享用英式下午茶、赠送鲜花与贺卡，家中布置春季花卉；当天教堂举行探访母堂的传统礼拜，餐厅与茶室全部订满，商场推出下午茶礼盒与香薰礼品。','注意与5月美国母亲节是两个日期，英国站需提前一个月单独备货；茶具、香薰蜡烛与鲜花包装为主推品类。'),
(25,'诺鲁孜节','Nowruz','2026-03-20',2026,'ME','波斯历新年（春分前后，2026年3月20日），中亚五国、伊朗、阿富汗等地最重要的节日，持续约两周。家中郑重摆放“七鲜桌”（Haft Seen）：发芽小麦草、彩绘彩蛋、金鱼缸、风信子、蒜、苹果、醋等七样以S开头的物品；除夕阖家守岁，初一拜年发红包，节后第13天全家外出踏青。','中亚市场全年最大消费节点，七鲜桌摆件与彩蛋套装为特色爆款；绿植、金鱼缸等场景商品可做套装，3月上旬完成上架。'),
(26,'诺鲁孜节','Nowruz','2027-03-21',2027,'ME','波斯历新年（春分前后，2026年3月20日），中亚五国、伊朗、阿富汗等地最重要的节日，持续约两周。家中郑重摆放“七鲜桌”（Haft Seen）：发芽小麦草、彩绘彩蛋、金鱼缸、风信子、蒜、苹果、醋等七样以S开头的物品；除夕阖家守岁，初一拜年发红包，节后第13天全家外出踏青。','中亚市场全年最大消费节点，七鲜桌摆件与彩蛋套装为特色爆款；绿植、金鱼缸等场景商品可做套装，3月上旬完成上架。'),
(27,'开斋节','Eid al-Fitr / Hari Raya Aidilfitri','2026-03-20',2026,'ME,SEA','斋月结束的盛大节日（2026年3月20日），一般放假3天。节前家家户户大扫除、购置新衣与家居装饰，门上挂星月拉旗与气球；首日清晨参加会礼，之后走亲访友、给孩子发绿色红包封，餐桌摆满甜食与点心，互赠礼盒。','节日服饰、礼盒与装饰三驾马车，节前两周集中出单；中东偏好华丽金色、东南亚偏好清新绿色，关键词共用但选品注意风格差异。'),
(28,'开斋节','Eid al-Fitr / Hari Raya Aidilfitri','2027-03-09',2027,'ME,SEA','斋月结束的盛大节日（2026年3月20日），一般放假3天。节前家家户户大扫除、购置新衣与家居装饰，门上挂星月拉旗与气球；首日清晨参加会礼，之后走亲访友、给孩子发绿色红包封，餐桌摆满甜食与点心，互赠礼盒。','节日服饰、礼盒与装饰三驾马车，节前两周集中出单；中东偏好华丽金色、东南亚偏好清新绿色，关键词共用但选品注意风格差异。'),
(29,'复活节','Easter Sunday','2026-04-05',2026,'NA,EU','春分月圆后的第一个星期日（2026年4月5日）。家庭以彩蛋、兔子、小鸡与春季花卉布置客厅与餐桌，复活节前夕教堂举行守夜礼拜；周日早晨儿童挎着寻蛋篮在庭院或教堂草坪参加寻蛋活动，中午家庭聚餐，吃火腿、十字面包与彩蛋。','彩蛋、兔子玩偶与寻蛋篮是儿童刚需；日期每年变动，须按当年日期倒推备货，染料套装、草丝等配件做组合可提客单。'),
(30,'复活节','Easter Sunday','2027-03-28',2027,'NA,EU','春分月圆后的第一个星期日（2026年4月5日）。家庭以彩蛋、兔子、小鸡与春季花卉布置客厅与餐桌，复活节前夕教堂举行守夜礼拜；周日早晨儿童挎着寻蛋篮在庭院或教堂草坪参加寻蛋活动，中午家庭聚餐，吃火腿、十字面包与彩蛋。','彩蛋、兔子玩偶与寻蛋篮是儿童刚需；日期每年变动，须按当年日期倒推备货，染料套装、草丝等配件做组合可提客单。'),
(31,'宋干节（泼水节）','Songkran Festival','2026-04-13',2026,'SEA','泰国传统新年，4月13–15日全国放假。人们手持水枪、水桶在街头互相泼水祈福，前往寺庙浴佛、堆沙塔，向长辈洒水行礼；清迈、普吉、芭提雅同时迎来旅游高峰，游客穿着花衬衫、佩戴防水手机袋全天参与泼水。','水枪与防水用品为绝对爆款，体积小重量轻适合空运快速补货；4月初即进入高峰，背包水枪与大容量水枪利润更高。'),
(32,'宋干节（泼水节）','Songkran Festival','2027-04-13',2027,'SEA','泰国传统新年，4月13–15日全国放假。人们手持水枪、水桶在街头互相泼水祈福，前往寺庙浴佛、堆沙塔，向长辈洒水行礼；清迈、普吉、芭提雅同时迎来旅游高峰，游客穿着花衬衫、佩戴防水手机袋全天参与泼水。','水枪与防水用品为绝对爆款，体积小重量轻适合空运快速补货；4月初即进入高峰，背包水枪与大容量水枪利润更高。'),
(33,'雄王祭祖日','Hung Kings'' Temple Festival','2026-04-26',2026,'SEA','越南农历三月初十（2026年4月26日）的国家级纪念日，全国放假1天。民众前往富寿省雄王庙祭祖，各地举行龙舟、摔跤、唱军鼓等民俗活动；家中与社区供桌摆放粽子、供品，门口悬挂国旗与节日横幅。','越南站春季营销节点，传统服饰奥黛与供品周边需求集中；粽子、供盘等商品可与越南春节供应链复用。'),
(34,'雄王祭祖日','Hung Kings'' Temple Festival','2027-04-19',2027,'SEA','越南农历三月初十（2026年4月26日）的国家级纪念日，全国放假1天。民众前往富寿省雄王庙祭祖，各地举行龙舟、摔跤、唱军鼓等民俗活动；家中与社区供桌摆放粽子、供品，门口悬挂国旗与节日横幅。','越南站春季营销节点，传统服饰奥黛与供品周边需求集中；粽子、供盘等商品可与越南春节供应链复用。'),
(35,'五月五日节','Cinco de Mayo','2026-05-05',2026,'LATAM','5月5日，纪念1862年墨西哥普埃布拉战役，在美国已演变为墨西哥文化狂欢日。街道与餐厅悬挂剪纸彩旗，参加者戴宽边帽、披披风、摇沙锤，现场供应塔可、龙舌兰与玛格丽特；酒吧与社区举办派对、游行和皮纳塔活动。','美国西语裔市场消费旺盛，宽边帽、沙锤与彩旗是派对刚需；4月中旬完成上架，充气仙人掌等大件适合户外场景。'),
(36,'五月五日节','Cinco de Mayo','2027-05-05',2027,'LATAM','5月5日，纪念1862年墨西哥普埃布拉战役，在美国已演变为墨西哥文化狂欢日。街道与餐厅悬挂剪纸彩旗，参加者戴宽边帽、披披风、摇沙锤，现场供应塔可、龙舌兰与玛格丽特；酒吧与社区举办派对、游行和皮纳塔活动。','美国西语裔市场消费旺盛，宽边帽、沙锤与彩旗是派对刚需；4月中旬完成上架，充气仙人掌等大件适合户外场景。'),
(37,'母亲节（美国）','Mother''s Day','2026-05-10',2026,'NA','每年5月第二个星期日（2026年5月10日），美国最重要的送礼节日之一。家中与餐厅以康乃馨、鲜花礼盒布置，子女请母亲吃早午餐、赠送珠宝、鲜花与水疗礼品；当天教堂为母亲举行祝福仪式，商场鲜花与礼品专柜排起长队。','女性礼品全年峰值，适合推高客单永生花与饰品；4月中旬完成上架，贺卡与礼盒包装直接影响转化，可提供定制服务溢价。'),
(38,'母亲节（美国）','Mother''s Day','2027-05-09',2027,'NA','每年5月第二个星期日（2026年5月10日），美国最重要的送礼节日之一。家中与餐厅以康乃馨、鲜花礼盒布置，子女请母亲吃早午餐、赠送珠宝、鲜花与水疗礼品；当天教堂为母亲举行祝福仪式，商场鲜花与礼品专柜排起长队。','女性礼品全年峰值，适合推高客单永生花与饰品；4月中旬完成上架，贺卡与礼盒包装直接影响转化，可提供定制服务溢价。'),
(39,'阵亡将士纪念日','Memorial Day','2026-05-25',2026,'NA','美国联邦假日，5月最后一个星期一（2026年5月25日），纪念历次战争中阵亡的军人。当天家庭在墓地或纪念碑献花圈、插小旗、佩戴罂粟花胸针；同时长周末标志夏季开始，家庭在后院烧烤、去湖边度假，红白蓝装饰随处可见。','爱国装饰与户外用品双需求，是夏季品类启动节点；墓碑小旗、花圈为节前刚需，户外烧烤用品可与暑期商品合并备货。'),
(40,'阵亡将士纪念日','Memorial Day','2027-05-31',2027,'NA','美国联邦假日，5月最后一个星期一（2026年5月25日），纪念历次战争中阵亡的军人。当天家庭在墓地或纪念碑献花圈、插小旗、佩戴罂粟花胸针；同时长周末标志夏季开始，家庭在后院烧烤、去湖边度假，红白蓝装饰随处可见。','爱国装饰与户外用品双需求，是夏季品类启动节点；墓碑小旗、花圈为节前刚需，户外烧烤用品可与暑期商品合并备货。'),
(41,'卫塞节','Vesak Day','2026-05-31',2026,'SEA','纪念佛陀诞生、成道与涅槃的节日（2026年5月31日，各国日期略有差异），东南亚佛教国家的公共假日。寺庙张挂佛教彩旗与莲花灯，举行浴佛、放生、布施与烛光绕行；家庭在佛龛供莲花、点蜡烛，民众穿白衣持戒行善。','莲花灯、佛像与浴佛盆在泰国、马来西亚、新加坡有稳定需求；5月中旬完成上架，佛教用品注意包装庄重以提高评价。'),
(42,'卫塞节','Vesak Day','2027-05-20',2027,'SEA','纪念佛陀诞生、成道与涅槃的节日（2026年5月31日，各国日期略有差异），东南亚佛教国家的公共假日。寺庙张挂佛教彩旗与莲花灯，举行浴佛、放生、布施与烛光绕行；家庭在佛龛供莲花、点蜡烛，民众穿白衣持戒行善。','莲花灯、佛像与浴佛盆在泰国、马来西亚、新加坡有稳定需求；5月中旬完成上架，佛教用品注意包装庄重以提高评价。'),
(43,'古尔邦节','Eid al-Adha / Hari Raya Haji','2026-05-27',2026,'ME,SEA','伊斯兰两大节日之一（2026年5月27日），纪念先知易卜拉欣献牲，放假约一周。首日清晨参加会礼，之后宰牲分赠亲友与穷人；节前家家户户购置新衣、打扫房屋、布置灯饰与餐桌，男性穿新长袍，节日期间走亲访友、互赠糖果点心。','中东与马来市场节日男装为高客单品类，灯饰装饰可与开斋节共用供应链；4月下旬完成上架，糖果盘、礼品包装等配件走量。'),
(44,'古尔邦节','Eid al-Adha / Hari Raya Haji','2027-05-16',2027,'ME,SEA','伊斯兰两大节日之一（2026年5月27日），纪念先知易卜拉欣献牲，放假约一周。首日清晨参加会礼，之后宰牲分赠亲友与穷人；节前家家户户购置新衣、打扫房屋、布置灯饰与餐桌，男性穿新长袍，节日期间走亲访友、互赠糖果点心。','中东与马来市场节日男装为高客单品类，灯饰装饰可与开斋节共用供应链；4月下旬完成上架，糖果盘、礼品包装等配件走量。'),
(45,'父亲节','Father''s Day','2026-06-21',2026,'NA','美国父亲节为6月第三个星期日（2026年6月21日）。家中在后院举办烧烤派对，布置工具与运动主题装饰，子女赠送工具、户外用品与定制礼品；当天也是高尔夫、钓鱼、看棒球的热门日子，餐厅推出牛排与烧烤套餐。','工具类、烧烤类是常青爆款，定制锤子、保温杯可做个性化溢价；5月下旬完成上架，礼品套装客单可做高。'),
(46,'父亲节','Father''s Day','2027-06-20',2027,'NA','美国父亲节为6月第三个星期日（2026年6月21日）。家中在后院举办烧烤派对，布置工具与运动主题装饰，子女赠送工具、户外用品与定制礼品；当天也是高尔夫、钓鱼、看棒球的热门日子，餐厅推出牛排与烧烤套餐。','工具类、烧烤类是常青爆款，定制锤子、保温杯可做个性化溢价；5月下旬完成上架，礼品套装客单可做高。'),
(47,'六月节（解放日）','Juneteenth','2026-06-19',2026,'NA','6月19日，纪念1865年美国黑奴获悉解放，2021年成为联邦假日。社区以红黑绿泛非色布置，举办游行、朗读、音乐节与家族团聚聚餐，街头售卖主题服饰、徽章与旗帜；节日近年认知度快速提升，商家参与度逐年增加。','新兴节日，增速快竞争小，泛非色服饰与装饰适合提前布局；5月完成上架，1865主题与红黑绿配色是核心识别元素。'),
(48,'六月节（解放日）','Juneteenth','2027-06-19',2027,'NA','6月19日，纪念1865年美国黑奴获悉解放，2021年成为联邦假日。社区以红黑绿泛非色布置，举办游行、朗读、音乐节与家族团聚聚餐，街头售卖主题服饰、徽章与旗帜；节日近年认知度快速提升，商家参与度逐年增加。','新兴节日，增速快竞争小，泛非色服饰与装饰适合提前布局；5月完成上架，1865主题与红黑绿配色是核心识别元素。'),
(49,'巴西情人节','Dia dos Namorados','2026-06-12',2026,'LATAM','巴西情人节为6月12日（圣安东尼奥节前夜），情侣互赠礼物、共进浪漫晚餐。餐厅与公寓以红心形气球、玫瑰与蜡烛布置，商场出售巧克力、饰品与内衣礼盒；当天还举办相亲、集体婚礼登记等活动。','避开2月情人节红海，针对巴西站单独备货；6月上旬为高峰，情侣饰品、巧克力与浪漫家居为主推品类。'),
(50,'巴西情人节','Dia dos Namorados','2027-06-12',2027,'LATAM','巴西情人节为6月12日（圣安东尼奥节前夜），情侣互赠礼物、共进浪漫晚餐。餐厅与公寓以红心形气球、玫瑰与蜡烛布置，商场出售巧克力、饰品与内衣礼盒；当天还举办相亲、集体婚礼登记等活动。','避开2月情人节红海，针对巴西站单独备货；6月上旬为高峰，情侣饰品、巧克力与浪漫家居为主推品类。'),
(51,'伊斯兰新年','Islamic New Year (Hijri)','2026-06-17',2026,'ME','伊斯兰历正月初一（2026年约6月17日），穆斯林举行宗教祈祷、家庭聚会与年度回顾。部分地区清真寺举办讲座，家庭更换新日历，以绿色与新月元素轻量布置；节日氛围庄重安静，消费规模远小于两大尔德节。','宗教贺卡、日历等轻量商品适合顺带布局，可与古尔邦节后的补货合并；不建议单独压大件库存。'),
(52,'伊斯兰新年','Islamic New Year (Hijri)','2027-06-07',2027,'ME','伊斯兰历正月初一（2026年约6月17日），穆斯林举行宗教祈祷、家庭聚会与年度回顾。部分地区清真寺举办讲座，家庭更换新日历，以绿色与新月元素轻量布置；节日氛围庄重安静，消费规模远小于两大尔德节。','宗教贺卡、日历等轻量商品适合顺带布局，可与古尔邦节后的补货合并；不建议单独压大件库存。'),
(53,'加拿大日','Canada Day','2026-07-01',2026,'NA','7月1日加拿大国庆日，全国放假。渥太华举行升旗仪式与庆典，各地社区以红白枫叶主题装饰，举办游行、烧烤与烟花；民众穿红白服装、佩戴枫叶配饰参加街头派对，晚间聚集观看烟花。','加拿大站7月主力节点，枫叶元素是与美国国庆的差异化卖点；6月中旬完成上架，红白派对套装走量稳定。'),
(54,'加拿大日','Canada Day','2027-07-01',2027,'NA','7月1日加拿大国庆日，全国放假。渥太华举行升旗仪式与庆典，各地社区以红白枫叶主题装饰，举办游行、烧烤与烟花；民众穿红白服装、佩戴枫叶配饰参加街头派对，晚间聚集观看烟花。','加拿大站7月主力节点，枫叶元素是与美国国庆的差异化卖点；6月中旬完成上架，红白派对套装走量稳定。'),
(55,'美国独立日','Independence Day','2026-07-04',2026,'NA','7月4日美国国庆，全国放假。各地举行大游行，家庭在后院或湖畔举办烧烤派对，悬挂国旗、红白蓝气球与拉旗；白天有棒球赛与音乐节，晚间燃放烟花、挥舞安全烟花棒，商场与社区中心布置爱国主题场景。','全年爱国主题消费峰值，6月初即进入流量高峰；国旗、派对用品走量巨大，遮阳篷、充气浮具等大件适合海外仓。'),
(56,'美国独立日','Independence Day','2027-07-04',2027,'NA','7月4日美国国庆，全国放假。各地举行大游行，家庭在后院或湖畔举办烧烤派对，悬挂国旗、红白蓝气球与拉旗；白天有棒球赛与音乐节，晚间燃放烟花、挥舞安全烟花棒，商场与社区中心布置爱国主题场景。','全年爱国主题消费峰值，6月初即进入流量高峰；国旗、派对用品走量巨大，遮阳篷、充气浮具等大件适合海外仓。'),
(57,'新加坡国庆日','Singapore National Day','2026-08-09',2026,'SEA','8月9日新加坡独立纪念日，全国放假。滨海湾举行盛大庆典检阅礼与演出，全民领取国庆Funpack礼包，组屋区张挂红白国旗与星月旗；社区举行升旗仪式、聚餐与嘉年华，晚间集体观看烟花。','新加坡站8月核心节点，红白配色与国庆周边走量；7月完成上架，助威道具与派对用品为节前刚需。'),
(58,'新加坡国庆日','Singapore National Day','2027-08-09',2027,'SEA','8月9日新加坡独立纪念日，全国放假。滨海湾举行盛大庆典检阅礼与演出，全民领取国庆Funpack礼包，组屋区张挂红白国旗与星月旗；社区举行升旗仪式、聚餐与嘉年华，晚间集体观看烟花。','新加坡站8月核心节点，红白配色与国庆周边走量；7月完成上架，助威道具与派对用品为节前刚需。'),
(59,'印尼独立日','Indonesian Independence Day','2026-08-17',2026,'SEA','8月17日印尼独立纪念日，全国放假。家家户户悬挂红白双色旗，社区举行爬油杆、布袋赛跑、吃虾片等民俗比赛，红色头巾与服饰热销；当天举行升国旗仪式，街区搭起比赛帐篷与聚餐。','国旗与民俗比赛道具需求集中，7月下旬进入高峰；红白配色头巾可同时覆盖日常穿戴与节日场景。'),
(60,'印尼独立日','Indonesian Independence Day','2027-08-17',2027,'SEA','8月17日印尼独立纪念日，全国放假。家家户户悬挂红白双色旗，社区举行爬油杆、布袋赛跑、吃虾片等民俗比赛，红色头巾与服饰热销；当天举行升国旗仪式，街区搭起比赛帐篷与聚餐。','国旗与民俗比赛道具需求集中，7月下旬进入高峰；红白配色头巾可同时覆盖日常穿戴与节日场景。'),
(61,'马来西亚国庆日','Malaysia National Day','2026-08-31',2026,'SEA','8月31日马来亚联合邦独立纪念日，全国放假。吉隆坡举行盛大游行与庆典，全城悬挂辉煌条纹国旗；民众穿峇迪衫、佩戴国旗手环，商场以国旗色布置，举办展销与嘉年华，晚间观看烟花。','国旗、峇迪衫与国庆周边在8月底走量；8月上旬完成上架，国旗配饰可多件装出售。'),
(62,'马来西亚国庆日','Malaysia National Day','2027-08-31',2027,'SEA','8月31日马来亚联合邦独立纪念日，全国放假。吉隆坡举行盛大游行与庆典，全城悬挂辉煌条纹国旗；民众穿峇迪衫、佩戴国旗手环，商场以国旗色布置，举办展销与嘉年华，晚间观看烟花。','国旗、峇迪衫与国庆周边在8月底走量；8月上旬完成上架，国旗配饰可多件装出售。'),
(63,'先知诞辰','Mawlid al-Nabi','2026-08-25',2026,'ME','伊斯兰历三月十二日（2026年约8月25日），纪念先知穆罕默德诞辰。清真寺张挂绿色灯饰与横幅，举行诵经与赞圣活动，向儿童发放甜点；家庭以绿色灯笼、贺卡做轻量装饰，准备清真糕点分享。','宗教氛围浓，绿色灯饰与贺卡有稳定小需求；8月中旬完成上架，适合与日常礼拜用品关联销售。'),
(64,'先知诞辰','Mawlid al-Nabi','2027-08-14',2027,'ME','伊斯兰历三月十二日（2026年约8月25日），纪念先知穆罕默德诞辰。清真寺张挂绿色灯饰与横幅，举行诵经与赞圣活动，向儿童发放甜点；家庭以绿色灯笼、贺卡做轻量装饰，准备清真糕点分享。','宗教氛围浓，绿色灯饰与贺卡有稳定小需求；8月中旬完成上架，适合与日常礼拜用品关联销售。'),
(65,'菲律宾圣诞季启动','Philippines Christmas "BER Months"','2026-09-01',2026,'SEA','菲律宾有全球最长圣诞季，从9月第一个星期（BER月份开始）即启动。家庭在门窗悬挂星灯Parol，播放圣诞歌曲，商场布置圣诞树与圣诞场景；9月起周末陆续有圣诞派对，装饰销售一直持续到12月。','东南亚最早的圣诞备货窗口，星灯Parol是菲律宾特色爆款；8月完成上架抢占首发流量，圣诞装饰销售周期长达4个月。'),
(66,'菲律宾圣诞季启动','Philippines Christmas "BER Months"','2027-09-01',2027,'SEA','菲律宾有全球最长圣诞季，从9月第一个星期（BER月份开始）即启动。家庭在门窗悬挂星灯Parol，播放圣诞歌曲，商场布置圣诞树与圣诞场景；9月起周末陆续有圣诞派对，装饰销售一直持续到12月。','东南亚最早的圣诞备货窗口，星灯Parol是菲律宾特色爆款；8月完成上架抢占首发流量，圣诞装饰销售周期长达4个月。'),
(67,'巴西独立日','Brazil Independence Day','2026-09-07',2026,'LATAM','9月7日巴西独立纪念日，全国放假。巴西利亚与里约举行阅兵与飞行表演，街头张挂黄绿国旗与串旗；民众穿黄绿主题T恤、挥舞喇叭参加游行，商场以国旗色布置促销。','巴西站9月爱国主题节点，9月初为高峰；国旗与黄绿服饰走量，足球元素可关联销售。'),
(68,'巴西独立日','Brazil Independence Day','2027-09-07',2027,'LATAM','9月7日巴西独立纪念日，全国放假。巴西利亚与里约举行阅兵与飞行表演，街头张挂黄绿国旗与串旗；民众穿黄绿主题T恤、挥舞喇叭参加游行，商场以国旗色布置促销。','巴西站9月爱国主题节点，9月初为高峰；国旗与黄绿服饰走量，足球元素可关联销售。'),
(69,'劳工节','Labor Day','2026-09-07',2026,'NA','美国与加拿大9月第一个星期一（2026年9月7日），长周末标志夏季结束。家庭举办最后一波烧烤野餐与泳池派对，商场借假期举行大促；街道与公园可见白色主题派对、户外游戏与跳蚤市场。','户外与烧烤用品夏季最后一波出清，零售平台普遍有大促可蹭流量；8月中下旬为高峰，注意控制库存避免节后积压。'),
(70,'劳工节','Labor Day','2027-09-06',2027,'NA','美国与加拿大9月第一个星期一（2026年9月7日），长周末标志夏季结束。家庭举办最后一波烧烤野餐与泳池派对，商场借假期举行大促；街道与公园可见白色主题派对、户外游戏与跳蚤市场。','户外与烧烤用品夏季最后一波出清，零售平台普遍有大促可蹭流量；8月中下旬为高峰，注意控制库存避免节后积压。'),
(71,'墨西哥独立日','Mexican Independence Day','2026-09-16',2026,'LATAM','9月16日多洛雷斯呼声纪念日，墨西哥最重要的国庆节日。9月15日深夜总统在国家宫敲响多洛雷斯钟、高呼爱国口号，全城挥舞绿白红国旗与响铃；16日举行阅兵，街头有骑术表演、墨西哥美食与马里亚奇音乐。','墨西哥站9月最大节点，国旗、宽边帽与绿白红装饰需求集中；9月上旬完成上架，响铃与沙锤是声音类刚需。'),
(72,'墨西哥独立日','Mexican Independence Day','2027-09-16',2027,'LATAM','9月16日多洛雷斯呼声纪念日，墨西哥最重要的国庆节日。9月15日深夜总统在国家宫敲响多洛雷斯钟、高呼爱国口号，全城挥舞绿白红国旗与响铃；16日举行阅兵，街头有骑术表演、墨西哥美食与马里亚奇音乐。','墨西哥站9月最大节点，国旗、宽边帽与绿白红装饰需求集中；9月上旬完成上架，响铃与沙锤是声音类刚需。'),
(73,'智利国庆日','Fiestas Patrias (Chile)','2026-09-18',2026,'LATAM','9月18–19日智利国庆长周末。家庭在fondas帐篷集市跳昆卡舞、吃烤肉、喝红酒，空中满是风筝；人们佩戴瓦索牛仔帽、披毛呢披风，红白蓝三色装饰遍布街头与庭院。','智利市场小而精，牛仔帽、风筝等民俗商品竞争小；9月上旬完成上架，烧烤工具可与北美暑期供应链复用。'),
(74,'智利国庆日','Fiestas Patrias (Chile)','2027-09-18',2027,'LATAM','9月18–19日智利国庆长周末。家庭在fondas帐篷集市跳昆卡舞、吃烤肉、喝红酒，空中满是风筝；人们佩戴瓦索牛仔帽、披毛呢披风，红白蓝三色装饰遍布街头与庭院。','智利市场小而精，牛仔帽、风筝等民俗商品竞争小；9月上旬完成上架，烧烤工具可与北美暑期供应链复用。'),
(75,'慕尼黑啤酒节','Oktoberfest','2026-09-19',2026,'EU','9月中下旬（2026年9月19日起）德国慕尼黑世界最大民俗节日，持续约两周。特蕾莎草坪搭起巨型啤酒帐篷，女性穿紧身裙Dirndl、男性穿皮裤Lederhosen，手持1升啤酒杯，现场有铜管乐队、旋转木马与椒盐卷饼、姜饼等集市食品。','主题装扮客单高，啤酒杯与蓝白格装饰全年可售、节前爆发；8月完成上架，套装（帽+杯+装饰）利润最高。'),
(76,'慕尼黑啤酒节','Oktoberfest','2027-09-18',2027,'EU','9月中下旬（2026年9月19日起）德国慕尼黑世界最大民俗节日，持续约两周。特蕾莎草坪搭起巨型啤酒帐篷，女性穿紧身裙Dirndl、男性穿皮裤Lederhosen，手持1升啤酒杯，现场有铜管乐队、旋转木马与椒盐卷饼、姜饼等集市食品。','主题装扮客单高，啤酒杯与蓝白格装饰全年可售、节前爆发；8月完成上架，套装（帽+杯+装饰）利润最高。'),
(77,'沙特国庆日','Saudi National Day','2026-09-23',2026,'ME','9月23日沙特阿拉伯国庆日，全国放假。利雅得举行烟花、飞行表演与娱乐活动，街道与商场以绿色国旗主题布置；民众穿绿色T恤、佩戴徽章与围巾，车灯与建筑亮起绿色灯光，节日消费氛围随愿景2030改革逐年升温。','海湾新兴电商节点，绿色服饰与配饰增速快；9月上旬完成上架，绿色围巾、车贴适合走量。'),
(78,'沙特国庆日','Saudi National Day','2027-09-23',2027,'ME','9月23日沙特阿拉伯国庆日，全国放假。利雅得举行烟花、飞行表演与娱乐活动，街道与商场以绿色国旗主题布置；民众穿绿色T恤、佩戴徽章与围巾，车灯与建筑亮起绿色灯光，节日消费氛围随愿景2030改革逐年升温。','海湾新兴电商节点，绿色服饰与配饰增速快；9月上旬完成上架，绿色围巾、车贴适合走量。'),
(79,'中秋节','Mid-Autumn Festival','2026-09-25',2026,'SEA','农历八月十五（2026年9月25日），东南亚华人普遍庆祝。节前晚辈送月饼礼盒，家中摆茶具赏月；当晚儿童手提兔子灯笼、花灯游园，街道与商场布置灯笼场景与秋季装饰，部分地区举办灯会与舞龙。','月饼模具与灯笼为特色品类，节前两周流量集中；茶具、玉兔摆件等中式礼品适合组合销售，注意食品进口限制，主推模具与包装。'),
(80,'中秋节','Mid-Autumn Festival','2027-09-15',2027,'SEA','农历八月十五（2026年9月25日），东南亚华人普遍庆祝。节前晚辈送月饼礼盒，家中摆茶具赏月；当晚儿童手提兔子灯笼、花灯游园，街道与商场布置灯笼场景与秋季装饰，部分地区举办灯会与舞龙。','月饼模具与灯笼为特色品类，节前两周流量集中；茶具、玉兔摆件等中式礼品适合组合销售，注意食品进口限制，主推模具与包装。'),
(81,'加拿大感恩节','Canadian Thanksgiving','2026-10-12',2026,'NA','加拿大感恩节为10月第二个星期一（2026年10月12日）。家庭以枫叶花环、南瓜与松果布置餐桌，享用火鸡或火腿丰收大餐；长周末恰逢赏枫高峰，人们前往郊野观赏红叶，商场布置秋季丰收场景。','南瓜、枫叶等秋季装饰比美国感恩节提前走量；9月下旬完成上架，丰收角、麦穗等摆件可与万圣节商品同期陈列。'),
(82,'加拿大感恩节','Canadian Thanksgiving','2027-10-11',2027,'NA','加拿大感恩节为10月第二个星期一（2026年10月12日）。家庭以枫叶花环、南瓜与松果布置餐桌，享用火鸡或火腿丰收大餐；长周末恰逢赏枫高峰，人们前往郊野观赏红叶，商场布置秋季丰收场景。','南瓜、枫叶等秋季装饰比美国感恩节提前走量；9月下旬完成上架，丰收角、麦穗等摆件可与万圣节商品同期陈列。'),
(83,'万圣节','Halloween','2026-10-31',2026,'NA,EU,LATAM','10月31日西方年度最具商业价值的装扮节日。10月起家庭在门前布置南瓜灯、墓碑、蜘蛛网与电动恐怖道具；31日傍晚儿童化妆穿服装、挎讨糖袋逐户讨糖，成年人参加变装派对与鬼屋活动，宠物也多有主题装扮。','全年最大装扮类消费节点，9月起进入高峰；服装、户外装饰、宠物服全品类开花，南瓜雕刻工具与假血化妆品适合做配件组合。'),
(84,'万圣节','Halloween','2027-10-31',2027,'NA,EU,LATAM','10月31日西方年度最具商业价值的装扮节日。10月起家庭在门前布置南瓜灯、墓碑、蜘蛛网与电动恐怖道具；31日傍晚儿童化妆穿服装、挎讨糖袋逐户讨糖，成年人参加变装派对与鬼屋活动，宠物也多有主题装扮。','全年最大装扮类消费节点，9月起进入高峰；服装、户外装饰、宠物服全品类开花，南瓜雕刻工具与假血化妆品适合做配件组合。'),
(85,'亡灵节','Día de los Muertos','2026-11-02',2026,'LATAM','11月1–2日墨西哥祭祖节日（1日为幼灵、2日为成灵），2008年入选非遗。家中搭设祭坛，铺万寿菊花瓣引路，摆放糖骷髅、逝者照片、蜡烛与生前喜爱的食物；街道张挂剪纸彩旗，女性扮卡特里娜、画糖骷髅妆容，墓地有通宵音乐守灵。','与万圣节明确区分：亡灵节色彩艳丽（橙紫为主）、家庭与宗教属性强；万寿菊、糖骷髅与卡特里娜是专属品类，溢价高竞争小。'),
(86,'亡灵节','Día de los Muertos','2027-11-02',2027,'LATAM','11月1–2日墨西哥祭祖节日（1日为幼灵、2日为成灵），2008年入选非遗。家中搭设祭坛，铺万寿菊花瓣引路，摆放糖骷髅、逝者照片、蜡烛与生前喜爱的食物；街道张挂剪纸彩旗，女性扮卡特里娜、画糖骷髅妆容，墓地有通宵音乐守灵。','与万圣节明确区分：亡灵节色彩艳丽（橙紫为主）、家庭与宗教属性强；万寿菊、糖骷髅与卡特里娜是专属品类，溢价高竞争小。'),
(87,'盖伊·福克斯之夜','Guy Fawkes Night','2026-11-05',2026,'EU','11月5日英国传统篝火焰火之夜，纪念1605年火药阴谋事件。傍晚社区点燃巨大篝火、燃放烟花，儿童佩戴面具、挥舞安全火花棒；人们在篝火旁烤香肠与棉花糖，因面具随影视作品符号化，节日有全球长尾关注度。','英国站11月特色节点，面具全球有长尾需求可常年在售；10月下旬完成上架，火花棒、篝火派对装饰为节前刚需。'),
(88,'盖伊·福克斯之夜','Guy Fawkes Night','2027-11-05',2027,'EU','11月5日英国传统篝火焰火之夜，纪念1605年火药阴谋事件。傍晚社区点燃巨大篝火、燃放烟花，儿童佩戴面具、挥舞安全火花棒；人们在篝火旁烤香肠与棉花糖，因面具随影视作品符号化，节日有全球长尾关注度。','英国站11月特色节点，面具全球有长尾需求可常年在售；10月下旬完成上架，火花棒、篝火派对装饰为节前刚需。'),
(89,'排灯节','Diwali','2026-11-08',2026,'ME,SEA','印度教灯节（2026年11月8日），持续5天。节前大扫除、绘制蓝果丽地画，当晚家家户户点亮陶土油灯与彩灯，门窗悬挂印度灯笼；5天内穿新衣、拜吉祥天女与象神、燃放烟花、互赠甜食礼盒，海湾印度裔社区同样隆重庆祝。','油灯、彩灯与蓝果丽用品为爆款，10月下旬进入高峰；面向海湾与新加坡南亚裔社区，神像与甜食注意宗教敏感性，主推装饰与灯饰。'),
(90,'排灯节','Diwali','2027-10-29',2027,'ME,SEA','印度教灯节（2026年11月8日），持续5天。节前大扫除、绘制蓝果丽地画，当晚家家户户点亮陶土油灯与彩灯，门窗悬挂印度灯笼；5天内穿新衣、拜吉祥天女与象神、燃放烟花、互赠甜食礼盒，海湾印度裔社区同样隆重庆祝。','油灯、彩灯与蓝果丽用品为爆款，10月下旬进入高峰；面向海湾与新加坡南亚裔社区，神像与甜食注意宗教敏感性，主推装饰与灯饰。'),
(91,'退伍军人节/荣军纪念日','Veterans Day / Remembrance Day','2026-11-11',2026,'NA,EU','11月11日美国退伍军人节与英联邦荣军纪念日。当天11时举行两分钟默哀，民众佩戴红色罂粟花胸针，教堂与纪念碑献花圈；商场、学校与政界人士出席纪念仪式，悬挂国旗，向退伍军人致谢。','罂粟胸针是标志性消耗品，10月起即有稳定采购；爱国主题装饰可与阵亡将士纪念日共用供应链。'),
(92,'退伍军人节/荣军纪念日','Veterans Day / Remembrance Day','2027-11-11',2027,'NA,EU','11月11日美国退伍军人节与英联邦荣军纪念日。当天11时举行两分钟默哀，民众佩戴红色罂粟花胸针，教堂与纪念碑献花圈；商场、学校与政界人士出席纪念仪式，悬挂国旗，向退伍军人致谢。','罂粟胸针是标志性消耗品，10月起即有稳定采购；爱国主题装饰可与阵亡将士纪念日共用供应链。'),
(93,'双十一购物节','Singles'' Day / 11.11 Sale','2026-11-11',2026,'NA,EU,SEA,LATAM','11月11日起源于中国的全球电商购物节。速卖通、Temu等跨境平台提前数周预热，发放优惠券并直播带货；当天24小时限时折扣，买家重点抢购美妆、3C、服饰与家居，包裹量为全年峰值之一。','卖家全年冲量节点，提前一个月提报平台活动；美妆套装、3C配件折扣引流效果最好，准备充足库存与促销物料。'),
(94,'双十一购物节','Singles'' Day / 11.11 Sale','2027-11-11',2027,'NA,EU,SEA,LATAM','11月11日起源于中国的全球电商购物节。速卖通、Temu等跨境平台提前数周预热，发放优惠券并直播带货；当天24小时限时折扣，买家重点抢购美妆、3C、服饰与家居，包裹量为全年峰值之一。','卖家全年冲量节点，提前一个月提报平台活动；美妆套装、3C配件折扣引流效果最好，准备充足库存与促销物料。'),
(95,'墨西哥 Buen Fin 购物节','El Buen Fin','2026-11-13',2026,'LATAM','墨西哥年度最大购物节，11月中旬长周末（2026年11月13日起），由政府与商界联合推动。家电、家具与百货折扣力度全年最大，商场延长营业时间、布置促销吊旗，民众以分期方式集中采购大件，被称为墨西哥版黑五。','墨西哥站黑五同级节点，家电与礼品类卖家重点参与；11月初完成促销物料与库存，价格标签与分期信息要清晰。'),
(96,'墨西哥 Buen Fin 购物节','El Buen Fin','2027-11-19',2027,'LATAM','墨西哥年度最大购物节，11月中旬长周末（2026年11月13日起），由政府与商界联合推动。家电、家具与百货折扣力度全年最大，商场延长营业时间、布置促销吊旗，民众以分期方式集中采购大件，被称为墨西哥版黑五。','墨西哥站黑五同级节点，家电与礼品类卖家重点参与；11月初完成促销物料与库存，价格标签与分期信息要清晰。'),
(97,'水灯节','Loy Krathong','2026-11-24',2026,'SEA','泰历十二月满月夜（2026年11月24日）。人们用蕉叶底座制作水灯，插上蜡烛、香与鲜花，放入河中祈福；清迈同时举办万人天灯活动，天空飘满天灯，街道有花车游行、选美与传统舞蹈表演，是泰国旅游热度最高的节日之一。','水灯底座、蜡烛与天灯为刚需，11月中旬为高峰；面向游客主推天灯与水灯DIY材料，注意各地禁放政策对需求节奏的影响。'),
(98,'水灯节','Loy Krathong','2027-11-13',2027,'SEA','泰历十二月满月夜（2026年11月24日）。人们用蕉叶底座制作水灯，插上蜡烛、香与鲜花，放入河中祈福；清迈同时举办万人天灯活动，天空飘满天灯，街道有花车游行、选美与传统舞蹈表演，是泰国旅游热度最高的节日之一。','水灯底座、蜡烛与天灯为刚需，11月中旬为高峰；面向游客主推天灯与水灯DIY材料，注意各地禁放政策对需求节奏的影响。'),
(99,'感恩节','Thanksgiving','2026-11-26',2026,'NA','美国最重要的家庭团圆节日，11月第四个星期四（2026年11月26日）。儿女返乡，上午观看梅西感恩节大游行，下午全家烤火鸡、布置南瓜与秋季藤条餐桌；晚间观看橄榄球赛，商场黑五预热从当日深夜开始。','火鸡厨具与秋季装饰常青；备货窗口紧接黑五，两节点合并备货，火鸡烤盘、餐桌装饰在11月初进入高峰。'),
(100,'感恩节','Thanksgiving','2027-11-25',2027,'NA','美国最重要的家庭团圆节日，11月第四个星期四（2026年11月26日）。儿女返乡，上午观看梅西感恩节大游行，下午全家烤火鸡、布置南瓜与秋季藤条餐桌；晚间观看橄榄球赛，商场黑五预热从当日深夜开始。','火鸡厨具与秋季装饰常青；备货窗口紧接黑五，两节点合并备货，火鸡烤盘、餐桌装饰在11月初进入高峰。'),
(101,'黑色星期五','Black Friday','2026-11-27',2026,'NA,EU,LATAM','感恩节后首日（2026年11月27日），全球折扣力度峰值。线下商场凌晨开门，顾客带折叠椅彻夜排队；线上同步推出限时秒杀，电子、家电、服饰为搜索热点，店铺张贴黑五海报与折扣标签。','全年最大出单日，海运大件须按45天提前期倒推；促销海报、价签等物料与商品同步准备，黑五周末承接至网一。'),
(102,'黑色星期五','Black Friday','2027-11-26',2027,'NA,EU,LATAM','感恩节后首日（2026年11月27日），全球折扣力度峰值。线下商场凌晨开门，顾客带折叠椅彻夜排队；线上同步推出限时秒杀，电子、家电、服饰为搜索热点，店铺张贴黑五海报与折扣标签。','全年最大出单日，海运大件须按45天提前期倒推；促销海报、价签等物料与商品同步准备，黑五周末承接至网一。'),
(103,'网络星期一','Cyber Monday','2026-11-30',2026,'NA,EU','感恩节后的星期一（2026年11月30日），线上专属购物节。上班族在节后第一天集中网购，3C数码、软件订阅、游戏外设与办公用品折扣集中，电商以免运费、限时秒杀延续黑五流量。','黑五承接节点，数码与游戏外设是主战场；11月上旬完成备货，键鼠、耳机等高周转品类可与黑五共用库存。'),
(104,'网络星期一','Cyber Monday','2027-11-29',2027,'NA,EU','感恩节后的星期一（2026年11月30日），线上专属购物节。上班族在节后第一天集中网购，3C数码、软件订阅、游戏外设与办公用品折扣集中，电商以免运费、限时秒杀延续黑五流量。','黑五承接节点，数码与游戏外设是主战场；11月上旬完成备货，键鼠、耳机等高周转品类可与黑五共用库存。'),
(105,'阿联酋国庆日','UAE National Day','2026-12-02',2026,'ME','12月2日阿联酋建国纪念日，全国放假。阿布扎比与迪拜举行阅兵、烟花与飞行表演，商场与街道以国旗四色（绿白黑红）布置；民众佩戴围巾、徽章，车身贴国旗色车贴，家庭在沙漠与海滩搭帐篷聚餐。','海湾高购买力节点，围巾、车贴等国旗色商品走量；11月中旬完成上架，四色手环、脸绘等派对用品适合家庭采购。'),
(106,'阿联酋国庆日','UAE National Day','2027-12-02',2027,'ME','12月2日阿联酋建国纪念日，全国放假。阿布扎比与迪拜举行阅兵、烟花与飞行表演，商场与街道以国旗四色（绿白黑红）布置；民众佩戴围巾、徽章，车身贴国旗色车贴，家庭在沙漠与海滩搭帐篷聚餐。','海湾高购买力节点，围巾、车贴等国旗色商品走量；11月中旬完成上架，四色手环、脸绘等派对用品适合家庭采购。'),
(107,'圣尼古拉斯节','Sinterklaas / St. Nicholas Day','2026-12-06',2026,'EU','12月5日圣尼古拉斯夜（荷兰12月6日庆祝），荷兰、比利时、德国等地儿童最重要的送礼节日。圣尼古拉斯戴主教帽、持权杖，助手把礼物装入礼物袋；儿童把靴子放在壁炉旁，6日拆字母巧克力、香料饼干与惊喜小礼物，全家玩“惊喜诗”游戏。','欧洲12月礼品季开端，针对低地国家差异化选品；主教帽、字母巧克力模具与饼干模具为特色品类，11月中旬完成上架。'),
(108,'圣尼古拉斯节','Sinterklaas / St. Nicholas Day','2027-12-06',2027,'EU','12月5日圣尼古拉斯夜（荷兰12月6日庆祝），荷兰、比利时、德国等地儿童最重要的送礼节日。圣尼古拉斯戴主教帽、持权杖，助手把礼物装入礼物袋；儿童把靴子放在壁炉旁，6日拆字母巧克力、香料饼干与惊喜小礼物，全家玩“惊喜诗”游戏。','欧洲12月礼品季开端，针对低地国家差异化选品；主教帽、字母巧克力模具与饼干模具为特色品类，11月中旬完成上架。'),
(109,'拉斯波萨达斯','Las Posadas','2026-12-16',2026,'LATAM','墨西哥12月16–24日连续九晚的圣诞巡游，重现圣母玛利亚寻找客栈。邻里组队持蜡烛游行、唱祈祷歌，每晚派对以皮纳塔为中心，儿童挥棒打破皮纳塔抢糖果；门口摆放纸袋烛灯照路，供应波佐莱汤与圣诞热饮。','墨西哥圣诞季特色节点，皮纳塔为派对刚需；12月上旬进入高峰，皮纳塔棒子、糖果填充与烛灯可做组合。'),
(110,'拉斯波萨达斯','Las Posadas','2027-12-16',2027,'LATAM','墨西哥12月16–24日连续九晚的圣诞巡游，重现圣母玛利亚寻找客栈。邻里组队持蜡烛游行、唱祈祷歌，每晚派对以皮纳塔为中心，儿童挥棒打破皮纳塔抢糖果；门口摆放纸袋烛灯照路，供应波佐莱汤与圣诞热饮。','墨西哥圣诞季特色节点，皮纳塔为派对刚需；12月上旬进入高峰，皮纳塔棒子、糖果填充与烛灯可做组合。'),
(111,'圣诞节','Christmas','2026-12-25',2026,'NA,EU,SEA,LATAM','12月25日全球最重要的宗教与商业节日。12月起家中搭圣诞树、挂装饰球与灯饰，门悬花环、壁炉挂圣诞袜；24日平安夜教堂礼拜、家庭交换礼物，25日圣诞大餐，儿童从降临节日历开始倒数整个12月。','全年最大备货季，海运大件须按45天提前期；10月起进入高峰，圣诞树、装饰红海拼设计与套装，降临日历需最早上架。'),
(112,'圣诞节','Christmas','2027-12-25',2027,'NA,EU,SEA,LATAM','12月25日全球最重要的宗教与商业节日。12月起家中搭圣诞树、挂装饰球与灯饰，门悬花环、壁炉挂圣诞袜；24日平安夜教堂礼拜、家庭交换礼物，25日圣诞大餐，儿童从降临节日历开始倒数整个12月。','全年最大备货季，海运大件须按45天提前期；10月起进入高峰，圣诞树、装饰红海拼设计与套装，降临日历需最早上架。'),
(113,'节礼日','Boxing Day','2026-12-26',2026,'NA,EU','12月26日英联邦国家公共假日。全年力度最大的清仓促销日之一，商场凌晨开门排起长队，圣诞商品大幅折扣；家庭在圣诞后第一天休息、观看体育赛事，并开始收纳圣诞树与装饰。','圣诞库存清仓节点，促销物料与节日收纳商品（收纳箱、树袋、装饰收纳盒）借势走量；12月中旬备好收纳品类库存。'),
(114,'节礼日','Boxing Day','2027-12-26',2027,'NA,EU','12月26日英联邦国家公共假日。全年力度最大的清仓促销日之一，商场凌晨开门排起长队，圣诞商品大幅折扣；家庭在圣诞后第一天休息、观看体育赛事，并开始收纳圣诞树与装饰。','圣诞库存清仓节点，促销物料与节日收纳商品（收纳箱、树袋、装饰收纳盒）借势走量；12月中旬备好收纳品类库存。'),
(115,'登霄夜','Isra and Mi’raj','2026-01-15',2026,'ME','伊斯兰历7月27日夜，纪念先知穆罕默德乘天马夜行耶路撒冷、登霄受礼。节前穆斯林家庭以金色与绿色为节日主色，在客厅布置新月星光串灯、耶路撒冷圆顶清真寺造型摆件，门挂绿色“Al-Isra wal-Mi’raj”标识；清真寺举办夜间讲座，餐桌备椰枣、甜点与果汁招待礼拜者。','宗教节庆消费集中在灯饰与家居布置，金色/绿色产品在马来与印尼市场走量；圆顶清真寺造型挂件、夜光星月装饰为差异化品类，提前一个月上架。'),
(116,'登霄夜','Isra and Mi’raj','2027-01-04',2027,'ME','伊斯兰历7月27日夜，纪念先知穆罕默德乘天马夜行耶路撒冷、登霄受礼。节前穆斯林家庭以金色与绿色为节日主色，在客厅布置新月星光串灯、耶路撒冷圆顶清真寺造型摆件，门挂绿色“Al-Isra wal-Mi’raj”标识；清真寺举办夜间讲座，餐桌备椰枣、甜点与果汁招待礼拜者。','宗教节庆消费集中在灯饰与家居布置，金色/绿色产品在马来与印尼市场走量；圆顶清真寺造型挂件、夜光星月装饰为差异化品类，提前一个月上架。'),
(117,'东正教圣诞节','Orthodox Christmas','2026-01-07',2026,'EU,ME','儒略历12月25日，即公历1月7日，俄罗斯、塞尔维亚、乌克兰、白俄罗斯及中亚东正教群体的重要节日。1月6日平安夜实行圣诞斋戒，家中铺白色桌布、摆放干草象征马槽，以金色、白色与深红为节日主色，点燃长蜡烛；午夜全家前往教堂参加彻夜礼拜，7日享用十二道素斋晚宴并互赠礼物，街头张挂雪花灯饰与耶稣降生布景。','东正教市场圣诞装饰窗口比天主教晚13天，可错峰清欧洲仓尾货；金色雪花、圣诞球与马槽摆件需求集中，关键词注意用 orthodox 提高精准度。'),
(118,'东正教圣诞节','Orthodox Christmas','2027-01-07',2027,'EU,ME','儒略历12月25日，即公历1月7日，俄罗斯、塞尔维亚、乌克兰、白俄罗斯及中亚东正教群体的重要节日。1月6日平安夜实行圣诞斋戒，家中铺白色桌布、摆放干草象征马槽，以金色、白色与深红为节日主色，点燃长蜡烛；午夜全家前往教堂参加彻夜礼拜，7日享用十二道素斋晚宴并互赠礼物，街头张挂雪花灯饰与耶稣降生布景。','东正教市场圣诞装饰窗口比天主教晚13天，可错峰清欧洲仓尾货；金色雪花、圣诞球与马槽摆件需求集中，关键词注意用 orthodox 提高精准度。'),
(119,'超级碗','Super Bowl Sunday','2026-02-08',2026,'NA','美国国家橄榄球联盟年度总决赛，常年在2月第二个星期日，是全美收视率最高的体育盛事。比赛从傍晚开始，家庭客厅改造成观赛主场：以两支决赛球队队色的气球、拉旗和横幅布置电视墙，餐桌摆满零食碗、饮品桶；人们穿着球队球衣或球星号码T恤，酒吧与餐厅架起大屏幕，中场秀期间举办主题派对，鸡翅、披萨与啤酒是标配，赛后还有赌局和颁奖话题。','体育流量节点，1月决赛球队确定后迎来采购高峰；通用橄榄球品类提前上架，印有具体球队/Super Bowl LX字样的商品赛前必须清完。'),
(120,'超级碗','Super Bowl Sunday','2027-02-14',2027,'NA','美国国家橄榄球联盟年度总决赛，常年在2月第二个星期日，是全美收视率最高的体育盛事。比赛从傍晚开始，家庭客厅改造成观赛主场：以两支决赛球队队色的气球、拉旗和横幅布置电视墙，餐桌摆满零食碗、饮品桶；人们穿着球队球衣或球星号码T恤，酒吧与餐厅架起大屏幕，中场秀期间举办主题派对，鸡翅、披萨与啤酒是标配，赛后还有赌局和颁奖话题。','体育流量节点，1月决赛球队确定后迎来采购高峰；通用橄榄球品类提前上架，印有具体球队/Super Bowl LX字样的商品赛前必须清完。'),
(121,'土拨鼠日','Groundhog Day','2026-02-02',2026,'NA','北美民间传统节日，每年2月2日，传说土拨鼠出洞：若看见自己的影子，冬天还将持续六周。节日色彩以棕色、深绿与冬日白为主，学校教室布置土拨鼠主题墙报、树洞手工与“春天还要等多久”倒计时卡片；宾州Punxsutawney举行盛大宣布仪式，家庭观看直播并购买土拨鼠毛绒玩偶，咖啡馆推出土拨鼠造型点心，是美国冬末趣味营销节点。','客单以儿童教室装饰与毛绒玩偶为主，1月底进入高峰；可与春季花园主题合并备货，土拨鼠造型宠物用品也有小热度。'),
(122,'土拨鼠日','Groundhog Day','2027-02-02',2027,'NA','北美民间传统节日，每年2月2日，传说土拨鼠出洞：若看见自己的影子，冬天还将持续六周。节日色彩以棕色、深绿与冬日白为主，学校教室布置土拨鼠主题墙报、树洞手工与“春天还要等多久”倒计时卡片；宾州Punxsutawney举行盛大宣布仪式，家庭观看直播并购买土拨鼠毛绒玩偶，咖啡馆推出土拨鼠造型点心，是美国冬末趣味营销节点。','客单以儿童教室装饰与毛绒玩偶为主，1月底进入高峰；可与春季花园主题合并备货，土拨鼠造型宠物用品也有小热度。'),
(123,'春节（华人新年）','Lunar New Year / Chinese New Year','2026-02-17',2026,'SEA','东南亚华人圈最重要的农历新年，马来西亚、新加坡、印尼均设公共假日（2026年2月17日）。节前数周大扫除、贴春联福字，牛车水与商场张满大红灯笼、桃花与年橘，以正红配金色为绝对主色；除夕吃团圆饭、鱼生捞起，初一穿红衣拜年发红包，街头举行舞狮舞龙与灯会，节令生肖吉祥物、红色年饼礼盒是走量爆款。','红色品类节前两周爆发，生肖吉祥物与红包封销量最大；注意当年生肖主题，大件桃花年橘走本地仓，跨境主推轻量装饰与利是封。'),
(124,'春节（华人新年）','Lunar New Year / Chinese New Year','2027-02-06',2027,'SEA','东南亚华人圈最重要的农历新年，马来西亚、新加坡、印尼均设公共假日（2026年2月17日）。节前数周大扫除、贴春联福字，牛车水与商场张满大红灯笼、桃花与年橘，以正红配金色为绝对主色；除夕吃团圆饭、鱼生捞起，初一穿红衣拜年发红包，街头举行舞狮舞龙与灯会，节令生肖吉祥物、红色年饼礼盒是走量爆款。','红色品类节前两周爆发，生肖吉祥物与红包封销量最大；注意当年生肖主题，大件桃花年橘走本地仓，跨境主推轻量装饰与利是封。'),
(125,'威尼斯狂欢节','Venice Carnival (Carnevale di Venezia)','2026-02-17',2026,'EU','意大利威尼斯年度盛事，圣灰星期三前约十天开始、忏悔星期二落幕（2026年2月17日）。整座水城以金、黑、深蓝与酒红为节日色彩，圣马可广场挂满彩旗与吊灯；人们佩戴华丽全脸面具、三角帽和复古长袍，贡多拉船夫盛装划船，街头有杂耍与古典乐表演，假面舞会在宫廷酒店通宵举行，面具羽毛扇是必备道具。','高端面具与复古服饰客单价高，节前两周集中出单；黑金配色羽毛面具辨识度最高，可搭配羽毛扇做组合套装。'),
(126,'威尼斯狂欢节','Venice Carnival (Carnevale di Venezia)','2027-02-09',2027,'EU','意大利威尼斯年度盛事，圣灰星期三前约十天开始、忏悔星期二落幕（2026年2月17日）。整座水城以金、黑、深蓝与酒红为节日色彩，圣马可广场挂满彩旗与吊灯；人们佩戴华丽全脸面具、三角帽和复古长袍，贡多拉船夫盛装划船，街头有杂耍与古典乐表演，假面舞会在宫廷酒店通宵举行，面具羽毛扇是必备道具。','高端面具与复古服饰客单价高，节前两周集中出单；黑金配色羽毛面具辨识度最高，可搭配羽毛扇做组合套装。'),
(127,'巴兰基亚狂欢节','Barranquilla Carnival','2026-02-14',2026,'LATAM','哥伦比亚巴兰基亚狂欢节，联合国非遗，圣灰星期三前的周六至周二举行（2026年2月14日开幕）。节日色彩浓烈，以红、黄、蓝、绿四色铺满大街小巷，Batalla de Flores花车大游行中舞者身着亮片舞裙、头戴羽毛冠抛洒鲜花；全城响起昆比亚鼓点，人们佩戴彩色面具与珠链参加街头Guacherna夜间游行，Marimonda小丑玩偶（长鼻花衣）是当地标志。','哥伦比亚市场全年最大装扮窗口，羽毛冠与亮片舞裙为主推；Marimonda小丑周边竞争小，鼓乐打击乐器与多色珠链适合多件装。'),
(128,'巴兰基亚狂欢节','Barranquilla Carnival','2027-02-06',2027,'LATAM','哥伦比亚巴兰基亚狂欢节，联合国非遗，圣灰星期三前的周六至周二举行（2026年2月14日开幕）。节日色彩浓烈，以红、黄、蓝、绿四色铺满大街小巷，Batalla de Flores花车大游行中舞者身着亮片舞裙、头戴羽毛冠抛洒鲜花；全城响起昆比亚鼓点，人们佩戴彩色面具与珠链参加街头Guacherna夜间游行，Marimonda小丑玩偶（长鼻花衣）是当地标志。','哥伦比亚市场全年最大装扮窗口，羽毛冠与亮片舞裙为主推；Marimonda小丑周边竞争小，鼓乐打击乐器与多色珠链适合多件装。'),
(129,'普珥节','Purim','2026-03-03',2026,'ME','犹太历阿达尔月14日，纪念犹太民族在波斯免遭灭族，以色列全民狂欢（2026年3月3日）。节日色彩明快，以紫、金、红为主，学校与会堂布置王冠、权杖、波斯宫廷主题装饰；儿童穿着圣经人物或创意变装服，佩戴面具参加游行，成人诵读《以斯帖记》、互赠美食篮（Mishloach Manot），街头举办变装派对，会堂气球与拉旗装点一新。','以色列儿童装扮节日，变装服与美食篮包装盒为刚需；王冠、权杖等宫廷主题在犹太市场精准度高，提前45天海运备货。'),
(130,'普珥节','Purim','2027-03-23',2027,'ME','犹太历阿达尔月14日，纪念犹太民族在波斯免遭灭族，以色列全民狂欢（2026年3月3日）。节日色彩明快，以紫、金、红为主，学校与会堂布置王冠、权杖、波斯宫廷主题装饰；儿童穿着圣经人物或创意变装服，佩戴面具参加游行，成人诵读《以斯帖记》、互赠美食篮（Mishloach Manot），街头举办变装派对，会堂气球与拉旗装点一新。','以色列儿童装扮节日，变装服与美食篮包装盒为刚需；王冠、权杖等宫廷主题在犹太市场精准度高，提前45天海运备货。'),
(131,'希腊独立日','Greek Independence Day','2026-03-25',2026,'EU','3月25日希腊国庆，纪念1821年脱离奥斯曼统治独立，同时适逢天使报喜日。全国以蓝白两色为节日主色，雅典宪法广场举行阅兵，卫城张挂蓝白灯光；学校组织游行，学生身穿蓝白校服、手持希腊小国旗，教堂举行感恩礼拜，家庭餐桌以蓝白桌旗、国旗气球布置，街头橱窗贴蓝白拉旗，海鲜与炸鳕鱼是当天传统食物。','蓝白主题品类可与塞浦路斯、以色列共享供应链；国旗与蓝白装饰需求集中在3月中旬，宗教+国庆双主题客单稳定。'),
(132,'希腊独立日','Greek Independence Day','2027-03-25',2027,'EU','3月25日希腊国庆，纪念1821年脱离奥斯曼统治独立，同时适逢天使报喜日。全国以蓝白两色为节日主色，雅典宪法广场举行阅兵，卫城张挂蓝白灯光；学校组织游行，学生身穿蓝白校服、手持希腊小国旗，教堂举行感恩礼拜，家庭餐桌以蓝白桌旗、国旗气球布置，街头橱窗贴蓝白拉旗，海鲜与炸鳕鱼是当天传统食物。','蓝白主题品类可与塞浦路斯、以色列共享供应链；国旗与蓝白装饰需求集中在3月中旬，宗教+国庆双主题客单稳定。'),
(133,'突尼斯独立日','Tunisia Independence Day','2026-03-20',2026,'ME','3月20日突尼斯独立纪念日，纪念1956年脱离法国独立。节日主色为国旗红与白，突尼斯城举行阅兵与授勋，街头悬挂红白国旗与横幅；学校布置独立日主题墙报，咖啡馆与商户悬挂彩灯，家庭以红白气球、星月标志装饰门庭，哈比卜·布尔吉巴大道举办庆祝游行，晚间还有音乐焰火表演。','北非市场小众节日竞争小，红白星月主题品类与土耳其市场供应链通用；适合中小卖家测北非站点，提前一个月上架。'),
(134,'突尼斯独立日','Tunisia Independence Day','2027-03-20',2027,'ME','3月20日突尼斯独立纪念日，纪念1956年脱离法国独立。节日主色为国旗红与白，突尼斯城举行阅兵与授勋，街头悬挂红白国旗与横幅；学校布置独立日主题墙报，咖啡馆与商户悬挂彩灯，家庭以红白气球、星月标志装饰门庭，哈比卜·布尔吉巴大道举办庆祝游行，晚间还有音乐焰火表演。','北非市场小众节日竞争小，红白星月主题品类与土耳其市场供应链通用；适合中小卖家测北非站点，提前一个月上架。'),
(135,'墨西哥圣烛节','Día de la Candelaria','2026-02-02',2026,'LATAM','墨西哥圣诞季收官日，每年2月2日。三王节面包里吃到圣婴小人的人要在这天请客，家家户户把马槽中的圣婴像换上新衣，以白色、天蓝与金色为节日主色，给圣婴穿上绣花披风戴上小冠冕；清晨捧蜡烛参加教堂祝圣游行，之后回家摆 Tamale 玉米粽塔、Atole 热饮招待亲友，客厅马槽周围点缀白金色 Papel Picado 镂空旗。','宗教节庆刚需：圣婴服饰、蜡烛与玉米粽蒸锅走量大；客单稳定但市场垂直，提前20天上架，主打墨西哥本地仓与美墨跨境。'),
(136,'墨西哥圣烛节','Día de la Candelaria','2027-02-02',2027,'LATAM','墨西哥圣诞季收官日，每年2月2日。三王节面包里吃到圣婴小人的人要在这天请客，家家户户把马槽中的圣婴像换上新衣，以白色、天蓝与金色为节日主色，给圣婴穿上绣花披风戴上小冠冕；清晨捧蜡烛参加教堂祝圣游行，之后回家摆 Tamale 玉米粽塔、Atole 热饮招待亲友，客厅马槽周围点缀白金色 Papel Picado 镂空旗。','宗教节庆刚需：圣婴服饰、蜡烛与玉米粽蒸锅走量大；客单稳定但市场垂直，提前20天上架，主打墨西哥本地仓与美墨跨境。'),
(137,'沙特建国日','Saudi Founding Day','2026-02-22',2026,'ME','沙特官方节日，纪念1727年沙特王国奠基，与9月绿色国庆不同，建国日主视觉为沙色、陶土棕与金色。利雅得各大商场以棕榈树、沙丘与传统陶瓮造型布置，男子穿米色长袍、披红格头巾跳 Ardah 剑舞，女子佩戴复古银饰展示 Najdi 村落文化；街头悬挂建国日徽章旗帜，晚间有传统音乐与烟火，咖啡馆供应豆蔻咖啡与椰枣宴。','沙色/棕金主题与绿色国庆供应链区隔，剑舞道具、传统纹样饰品竞争小；节前两周集中爆发，适合做套装组合。'),
(138,'沙特建国日','Saudi Founding Day','2027-02-22',2027,'ME','沙特官方节日，纪念1727年沙特王国奠基，与9月绿色国庆不同，建国日主视觉为沙色、陶土棕与金色。利雅得各大商场以棕榈树、沙丘与传统陶瓮造型布置，男子穿米色长袍、披红格头巾跳 Ardah 剑舞，女子佩戴复古银饰展示 Najdi 村落文化；街头悬挂建国日徽章旗帜，晚间有传统音乐与烟火，咖啡馆供应豆蔻咖啡与椰枣宴。','沙色/棕金主题与绿色国庆供应链区隔，剑舞道具、传统纹样饰品竞争小；节前两周集中爆发，适合做套装组合。'),
(139,'爱沙尼亚独立日','Estonian Independence Day','2026-02-24',2026,'EU','纪念1918年《独立宣言》发布，是爱沙尼亚最重要的国庆日。节日色彩为蓝、黑、白三色，塔林自由广场举行阅兵，总统府举办招待会；傍晚民众手持火把与蓝黑白灯笼参加火炬游行，家家户户窗台点燃蓝白蜡烛，学校张贴三色海报与国旗手工，餐厅供应国菜黑布丁与酸菜，晚间礼花照亮中世纪老城。','波罗的海小众市场，蓝黑白三色品类供应链与立陶宛/拉脱维亚通用；窗台电子蜡烛安全款更受公寓家庭欢迎。'),
(140,'爱沙尼亚独立日','Estonian Independence Day','2027-02-24',2027,'EU','纪念1918年《独立宣言》发布，是爱沙尼亚最重要的国庆日。节日色彩为蓝、黑、白三色，塔林自由广场举行阅兵，总统府举办招待会；傍晚民众手持火把与蓝黑白灯笼参加火炬游行，家家户户窗台点燃蓝白蜡烛，学校张贴三色海报与国旗手工，餐厅供应国菜黑布丁与酸菜，晚间礼花照亮中世纪老城。','波罗的海小众市场，蓝黑白三色品类供应链与立陶宛/拉脱维亚通用；窗台电子蜡烛安全款更受公寓家庭欢迎。'),
(141,'科威特国庆','Kuwait National Day','2026-02-25',2026,'ME','科威特国庆为2月25日，次日26日为解放日，全国连庆两天。节日主色取自国旗的绿、白、红、黑，科威特地标大楼打出国旗灯光秀，街头车辆插满小旗、缠满绿白彩带巡游；孩子们在脸上画新月标志，穿着印有国旗图案的衣服，商场以气球拱门与彩灯布置，家庭到海滨大道野餐看烟火，随处可听到传统鼓乐。','海湾高消费市场，车旗、脸彩与发光玩具是儿童刚需；适合做多件装与亲子套装，节前10天冲刺。'),
(142,'科威特国庆','Kuwait National Day','2027-02-25',2027,'ME','科威特国庆为2月25日，次日26日为解放日，全国连庆两天。节日主色取自国旗的绿、白、红、黑，科威特地标大楼打出国旗灯光秀，街头车辆插满小旗、缠满绿白彩带巡游；孩子们在脸上画新月标志，穿着印有国旗图案的衣服，商场以气球拱门与彩灯布置，家庭到海滨大道野餐看烟火，随处可听到传统鼓乐。','海湾高消费市场，车旗、脸彩与发光玩具是儿童刚需；适合做多件装与亲子套装，节前10天冲刺。'),
(143,'多米尼加独立日','Dominican Independence Day','2026-02-27',2026,'LATAM','多米尼加共和国1844年脱离海地独立的纪念日，每年2月27日，海外侨民（尤其美国纽约、迈阿密）同步庆祝。节日色彩为国旗的红、白、蓝，圣多明各举行盛大阅兵与花车游行，学校组织学生穿红蓝白校服游行；家门口悬挂国旗，餐桌铺国旗桌布，供应 Mangu 香蕉泥与炸猪皮，晚间海滨燃放烟火，街头有 Merengue 乐队巡演。','美国西语侨民市场容量大，红蓝白品类与美国国庆供应链部分通用；多米尼加专属国旗图案产品溢价高。'),
(144,'多米尼加独立日','Dominican Independence Day','2027-02-27',2027,'LATAM','多米尼加共和国1844年脱离海地独立的纪念日，每年2月27日，海外侨民（尤其美国纽约、迈阿密）同步庆祝。节日色彩为国旗的红、白、蓝，圣多明各举行盛大阅兵与花车游行，学校组织学生穿红蓝白校服游行；家门口悬挂国旗，餐桌铺国旗桌布，供应 Mangu 香蕉泥与炸猪皮，晚间海滨燃放烟火，街头有 Merengue 乐队巡演。','美国西语侨民市场容量大，红蓝白品类与美国国庆供应链部分通用；多米尼加专属国旗图案产品溢价高。'),
(145,'保加利亚三月节','Baba Marta Day','2026-03-01',2026,'EU','保加利亚千年民俗节日，3月1日迎接“三月奶奶” Baba Marta。人们互相赠送红白两色 Martenitsa 护身符——红白人偶 Pizho 与 Penda、绒球穗带，佩戴在胸前或手腕，直到看见第一只鹳或燕子，再把它挂到开花的树枝上祈求健康。节日色彩就是纯粹的红白两色，集市挂满红白绒线饰品，学校教孩子编织三月结，家中摆放陶土“三月奶奶”玩偶。','红白编织饰品客单低但走量极大，可做多件装全家套餐；绒球、流苏配件与手工DIY材料包在欧洲站受欢迎。'),
(146,'保加利亚三月节','Baba Marta Day','2027-03-01',2027,'EU','保加利亚千年民俗节日，3月1日迎接“三月奶奶” Baba Marta。人们互相赠送红白两色 Martenitsa 护身符——红白人偶 Pizho 与 Penda、绒球穗带，佩戴在胸前或手腕，直到看见第一只鹳或燕子，再把它挂到开花的树枝上祈求健康。节日色彩就是纯粹的红白两色，集市挂满红白绒线饰品，学校教孩子编织三月结，家中摆放陶土“三月奶奶”玩偶。','红白编织饰品客单低但走量极大，可做多件装全家套餐；绒球、流苏配件与手工DIY材料包在欧洲站受欢迎。'),
(147,'立陶宛恢复独立日','Lithuanian Restoration of Independence Day','2026-03-11',2026,'EU','纪念1990年3月11日立陶宛成为首个宣布脱离苏联独立的加盟共和国。节日主色为黄、绿、红三色，维尔纽斯独立广场举行升旗与阅兵， Gediminas 城堡打出三色灯光；人们佩戴三色胸花与腕带参加音乐会，学校布置独立主题展览，街头有手工艺品集市，傍晚点燃三色烟花，咖啡馆供应立陶宛蜂蜜啤酒。','波罗的海三国节日供应链通用，黄绿红配色注意与玻利维亚区分；加入立陶宛国徽 Vytis 骑士元素提高精准度。'),
(148,'立陶宛恢复独立日','Lithuanian Restoration of Independence Day','2027-03-11',2027,'EU','纪念1990年3月11日立陶宛成为首个宣布脱离苏联独立的加盟共和国。节日主色为黄、绿、红三色，维尔纽斯独立广场举行升旗与阅兵， Gediminas 城堡打出三色灯光；人们佩戴三色胸花与腕带参加音乐会，学校布置独立主题展览，街头有手工艺品集市，傍晚点燃三色烟花，咖啡馆供应立陶宛蜂蜜啤酒。','波罗的海三国节日供应链通用，黄绿红配色注意与玻利维亚区分；加入立陶宛国徽 Vytis 骑士元素提高精准度。'),
(149,'匈牙利民族日','Hungarian National Day (1848 Revolution)','2026-03-15',2026,'EU','纪念1848年匈牙利反对哈布斯堡王朝的革命与独立战争。节日色彩为红、白、绿三色，布达佩斯国会大厦前举行升旗典礼，人们几乎人人佩戴红白绿三色圆形 Kokárda 布花胸章；市民登上布达城堡参加朗诵与军乐表演，多瑙河畔有民俗集市与传统美食 Lángos 炸饼，傍晚燃放烟花，博物馆当天免费开放。','三色 Kokárda 胸章是全民刚需、当天佩戴率极高，轻便好走量；注意与意大利/墨西哥等红绿白市场做图案区隔。'),
(150,'匈牙利民族日','Hungarian National Day (1848 Revolution)','2027-03-15',2027,'EU','纪念1848年匈牙利反对哈布斯堡王朝的革命与独立战争。节日色彩为红、白、绿三色，布达佩斯国会大厦前举行升旗典礼，人们几乎人人佩戴红白绿三色圆形 Kokárda 布花胸章；市民登上布达城堡参加朗诵与军乐表演，多瑙河畔有民俗集市与传统美食 Lángos 炸饼，傍晚燃放烟花，博物馆当天免费开放。','三色 Kokárda 胸章是全民刚需、当天佩戴率极高，轻便好走量；注意与意大利/墨西哥等红绿白市场做图案区隔。'),
(151,'法雅节','Las Fallas','2026-03-19',2026,'EU','西班牙瓦伦西亚年度火节，3月15日起全城摆放巨型纸偶 Ninot 雕塑（讽刺名人与时事），每天午后市政厅广场举行震耳欲聋的 Mascletà 爆竹秀，18日深夜有灯火烟花秀，19日圣约瑟夫日夜间 Cremà 焚烧所有法雅人偶，火光映红全城。节日色彩为金、红与象牙白，Fallera 女子梳发髻、插金梳、穿金线刺绣长裙向圣母献花，鲜花拼成巨大圣母披风。','节后即焚的属性让节日纪念品在游客中热销；金梳、折扇、小纸偶冰箱贴为主推，安全型派对烟花适合家庭场景。'),
(152,'法雅节','Las Fallas','2027-03-19',2027,'EU','西班牙瓦伦西亚年度火节，3月15日起全城摆放巨型纸偶 Ninot 雕塑（讽刺名人与时事），每天午后市政厅广场举行震耳欲聋的 Mascletà 爆竹秀，18日深夜有灯火烟花秀，19日圣约瑟夫日夜间 Cremà 焚烧所有法雅人偶，火光映红全城。节日色彩为金、红与象牙白，Fallera 女子梳发髻、插金梳、穿金线刺绣长裙向圣母献花，鲜花拼成巨大圣母披风。','节后即焚的属性让节日纪念品在游客中热销；金梳、折扇、小纸偶冰箱贴为主推，安全型派对烟花适合家庭场景。'),
(153,'巴基斯坦日','Pakistan Day','2026-03-23',2026,'ME','纪念1940年拉合尔决议（穆斯林联盟提出建国）与1956年巴基斯坦首部宪法。伊斯兰堡举行盛大阅兵，展示战机与导弹，节日主色为国旗的深绿与白，新月五角星标志无处不在；大街小巷张挂绿白彩旗与灯笼，孩子们穿绿色新衣、脸上画星月，学校举办演讲与诗朗诵，家庭走亲访友互送甜点，晚间各地放烟火庆祝。','两亿人口市场，绿白星月品类与穆斯林节庆供应链通用；儿童绿色服饰与脸彩走量，国旗大件走本地仓。'),
(154,'巴基斯坦日','Pakistan Day','2027-03-23',2027,'ME','纪念1940年拉合尔决议（穆斯林联盟提出建国）与1956年巴基斯坦首部宪法。伊斯兰堡举行盛大阅兵，展示战机与导弹，节日主色为国旗的深绿与白，新月五角星标志无处不在；大街小巷张挂绿白彩旗与灯笼，孩子们穿绿色新衣、脸上画星月，学校举办演讲与诗朗诵，家庭走亲访友互送甜点，晚间各地放烟火庆祝。','两亿人口市场，绿白星月品类与穆斯林节庆供应链通用；儿童绿色服饰与脸彩走量，国旗大件走本地仓。'),
(155,'逾越节','Passover (Pesach)','2026-04-02',2026,'ME','犹太教三大朝圣节之一，纪念以色列人出埃及，节期7天（以色列）至8天（海外），家宴 Seder 在首夜举行。节日色彩以白、银、深紫与酒红为主，餐桌铺白色桌布，摆 Seder Plate 六格餐盘、无酵饼盒与银杯 Elijah 杯，家中收尽一切发酵食品；家人头戴圆帽诵读哈加达，门挂“Happy Passover”装饰，厨房换上逾越节专用餐具，桌中央点缀白花与葡萄藤。','Seder 餐具与无酵饼周边是节日刚需，深紫酒红配色辨识度高；面向以色列与北美犹太社区，提前45天海运备货。'),
(156,'逾越节','Passover (Pesach)','2027-04-22',2027,'ME','犹太教三大朝圣节之一，纪念以色列人出埃及，节期7天（以色列）至8天（海外），家宴 Seder 在首夜举行。节日色彩以白、银、深紫与酒红为主，餐桌铺白色桌布，摆 Seder Plate 六格餐盘、无酵饼盒与银杯 Elijah 杯，家中收尽一切发酵食品；家人头戴圆帽诵读哈加达，门挂“Happy Passover”装饰，厨房换上逾越节专用餐具，桌中央点缀白花与葡萄藤。','Seder 餐具与无酵饼周边是节日刚需，深紫酒红配色辨识度高；面向以色列与北美犹太社区，提前45天海运备货。'),
(157,'耶稣受难日','Good Friday','2026-04-03',2026,'EU,LATAM','复活节前的星期五，纪念耶稣受难，是基督教世界最肃穆的节日。教堂撤去鲜花、祭坛覆盖黑布或紫布，以深紫、黑色与原木色为主，信众佩戴十字架参加苦路游行，巴西、菲律宾等国信徒重演十四处苦路；家中点燃长蜡烛、摆荆棘冠与十字架装饰，禁食不食肉，餐桌只上十字热面包与鱼汤，商店橱窗以紫纱与白百合布置，午后三时全国鸣钟默祷。','与复活节彩蛋品类形成区隔，深紫色宗教布艺、十字架装饰为主推；热面包模具与紫纱桌旗在拉美市场稳定出单。'),
(158,'耶稣受难日','Good Friday','2027-03-26',2027,'EU,LATAM','复活节前的星期五，纪念耶稣受难，是基督教世界最肃穆的节日。教堂撤去鲜花、祭坛覆盖黑布或紫布，以深紫、黑色与原木色为主，信众佩戴十字架参加苦路游行，巴西、菲律宾等国信徒重演十四处苦路；家中点燃长蜡烛、摆荆棘冠与十字架装饰，禁食不食肉，餐桌只上十字热面包与鱼汤，商店橱窗以紫纱与白百合布置，午后三时全国鸣钟默祷。','与复活节彩蛋品类形成区隔，深紫色宗教布艺、十字架装饰为主推；热面包模具与紫纱桌旗在拉美市场稳定出单。'),
(159,'却克里王朝纪念日','Chakri Memorial Day','2026-04-06',2026,'SEA','泰国法定假日，纪念却克里王朝（曼谷王朝）1782年开国及历代国王，拉玛一世曾建都曼谷。节日主色为王室黄与金色，曼谷大皇宫与玉佛寺举行宗教仪式，王室成员赴王家纪念柱献花圈；民众穿上黄色衣服入寺布施，向拉玛五世骑马铜像敬献花环，街道悬挂王旗与黄色彩旗，家中摆国王画像与万寿菊花环，商场橱窗以金箔莲花布置。','泰国王室主题节点，黄色品类与国王生日/宋干节供应链通用；已故国王纪念周边注意选用官方通用的敬意设计。'),
(160,'却克里王朝纪念日','Chakri Memorial Day','2027-04-06',2027,'SEA','泰国法定假日，纪念却克里王朝（曼谷王朝）1782年开国及历代国王，拉玛一世曾建都曼谷。节日主色为王室黄与金色，曼谷大皇宫与玉佛寺举行宗教仪式，王室成员赴王家纪念柱献花圈；民众穿上黄色衣服入寺布施，向拉玛五世骑马铜像敬献花环，街道悬挂王旗与黄色彩旗，家中摆国王画像与万寿菊花环，商场橱窗以金箔莲花布置。','泰国王室主题节点，黄色品类与国王生日/宋干节供应链通用；已故国王纪念周边注意选用官方通用的敬意设计。'),
(161,'荷兰国王节','King’s Day (Koningsdag)','2026-04-27',2026,'EU','荷兰最狂热的全国派对，庆祝威廉-亚历山大国王生日（4月27日）。整个国家变成橙色海洋：运河上挤满橙色小船和水上派对，阿姆斯特丹街头摆摊举行全民跳蚤市场 Vrijmarkt，人们戴橙色假发、橙色皇冠、羽毛 boa，脸上涂红白蓝国旗色；广场响起电子乐，啤酒与橙色甜点畅销，孩子们穿橙衣街头卖艺，全城没有一辆汽车，处处是橙色气球与三角旗。','橙色是唯一关键词：假发、皇冠、T恤等轻量装扮品节前一周爆发；海运提前45天，可搭配荷兰国旗红白蓝做组合。'),
(162,'荷兰国王节','King’s Day (Koningsdag)','2027-04-27',2027,'EU','荷兰最狂热的全国派对，庆祝威廉-亚历山大国王生日（4月27日）。整个国家变成橙色海洋：运河上挤满橙色小船和水上派对，阿姆斯特丹街头摆摊举行全民跳蚤市场 Vrijmarkt，人们戴橙色假发、橙色皇冠、羽毛 boa，脸上涂红白蓝国旗色；广场响起电子乐，啤酒与橙色甜点畅销，孩子们穿橙衣街头卖艺，全城没有一辆汽车，处处是橙色气球与三角旗。','橙色是唯一关键词：假发、皇冠、T恤等轻量装扮品节前一周爆发；海运提前45天，可搭配荷兰国旗红白蓝做组合。'),
(163,'墨西哥儿童节','Día del Niño (Children’s Day)','2026-04-30',2026,'LATAM','墨西哥法定儿童节，4月30日，是玩具、童装和糖果全年最旺的销售窗口之一。学校停课半天举办嘉年华：教室挂满彩色气球与拉旗，孩子们穿便装参加游戏、抽奖和 Piñata 皮纳塔砸糖；家长带孩子去游乐场、吃蛋糕，餐厅推出儿童免单活动，商场布置卡通人偶合影区，糖果色（粉、黄、青、薄荷绿）是主视觉，家庭聚会餐桌摆满纸杯蛋糕与糖果袋。','玩具类卖家必争节点，皮纳塔与糖果袋为家庭聚会刚需；注意与圣诞、三王节玩具季错峰，轻量玩具走跨境、大件走本地仓。'),
(164,'墨西哥儿童节','Día del Niño (Children’s Day)','2027-04-30',2027,'LATAM','墨西哥法定儿童节，4月30日，是玩具、童装和糖果全年最旺的销售窗口之一。学校停课半天举办嘉年华：教室挂满彩色气球与拉旗，孩子们穿便装参加游戏、抽奖和 Piñata 皮纳塔砸糖；家长带孩子去游乐场、吃蛋糕，餐厅推出儿童免单活动，商场布置卡通人偶合影区，糖果色（粉、黄、青、薄荷绿）是主视觉，家庭聚会餐桌摆满纸杯蛋糕与糖果袋。','玩具类卖家必争节点，皮纳塔与糖果袋为家庭聚会刚需；注意与圣诞、三王节玩具季错峰，轻量玩具走跨境、大件走本地仓。'),
(165,'越南统一日','Vietnamese Reunification Day','2026-04-30',2026,'SEA','4月30日是越南“南方解放日”，纪念1975年南北统一，与5月1日劳动节相连形成四天长假，是越南人出行、办婚礼和装修的高峰。街头张挂金星红旗与红横幅，胡志明市举行阅兵与游行，节日主色为红与金；家庭利用长假布置新居、采购家电与婚庆用品，商场以红色拱门和金箔装饰，景点与咖啡馆人满为患，晚间有烟火表演。','长假带动家居、婚庆与出游消费，红色节庆品类与春节供应链通用；家电装饰大件走本地仓，饰品小物适合跨境。'),
(166,'越南统一日','Vietnamese Reunification Day','2027-04-30',2027,'SEA','4月30日是越南“南方解放日”，纪念1975年南北统一，与5月1日劳动节相连形成四天长假，是越南人出行、办婚礼和装修的高峰。街头张挂金星红旗与红横幅，胡志明市举行阅兵与游行，节日主色为红与金；家庭利用长假布置新居、采购家电与婚庆用品，商场以红色拱门和金箔装饰，景点与咖啡馆人满为患，晚间有烟火表演。','长假带动家居、婚庆与出游消费，红色节庆品类与春节供应链通用；家电装饰大件走本地仓，饰品小物适合跨境。'),
(167,'俄罗斯胜利日','Victory Day (Russia)','2026-05-09',2026,'EU','俄罗斯及独联体最隆重的纪念日，纪念1945年对德战争胜利。莫斯科红场举行阅兵，节日主色为圣乔治丝带的橙黑两色，配以红旗；人们把橙黑丝带系在胸前、书包和车镜上，向烈士墓献红色康乃馨，傍晚放和平鸽与烟火，大街小巷挂满“胜利日”横幅与红军旗；老兵穿军装挂满勋章出席纪念会，家庭看《这里黎明静悄悄》等战争老电影。','橙黑圣乔治丝带与红康乃馨是全民刚需，轻便好走量；历史纪念题材严肃，避免娱乐化设计，主打庄重通用元素。'),
(168,'俄罗斯胜利日','Victory Day (Russia)','2027-05-09',2027,'EU','俄罗斯及独联体最隆重的纪念日，纪念1945年对德战争胜利。莫斯科红场举行阅兵，节日主色为圣乔治丝带的橙黑两色，配以红旗；人们把橙黑丝带系在胸前、书包和车镜上，向烈士墓献红色康乃馨，傍晚放和平鸽与烟火，大街小巷挂满“胜利日”横幅与红军旗；老兵穿军装挂满勋章出席纪念会，家庭看《这里黎明静悄悄》等战争老电影。','橙黑圣乔治丝带与红康乃馨是全民刚需，轻便好走量；历史纪念题材严肃，避免娱乐化设计，主打庄重通用元素。'),
(169,'挪威宪法日','Norwegian Constitution Day (Syttende Mai)','2026-05-17',2026,'EU','挪威1814年宪法签署纪念日，也是全球最童趣的国庆：奥斯陆举行小学生游行，孩子们挥舞国旗、吹号打鼓穿过王宫，王室在阳台挥手。节日主色为国旗红、蓝、白，人人穿 Bunad 刺绣民族盛装，胸前别国旗徽章；街头到处是腊肠、冰淇淋与气泡水，女孩头发系红白蓝丝带，家中餐桌摆奶油蛋糕与国旗牙签，家庭聚会从清晨香槟早餐持续到夜晚。','国旗小物与派对餐饮周边需求集中，民族风刺绣服饰客单高；红蓝白通用素材可做挪威专属图案提高溢价。'),
(170,'挪威宪法日','Norwegian Constitution Day (Syttende Mai)','2027-05-17',2027,'EU','挪威1814年宪法签署纪念日，也是全球最童趣的国庆：奥斯陆举行小学生游行，孩子们挥舞国旗、吹号打鼓穿过王宫，王室在阳台挥手。节日主色为国旗红、蓝、白，人人穿 Bunad 刺绣民族盛装，胸前别国旗徽章；街头到处是腊肠、冰淇淋与气泡水，女孩头发系红白蓝丝带，家中餐桌摆奶油蛋糕与国旗牙签，家庭聚会从清晨香槟早餐持续到夜晚。','国旗小物与派对餐饮周边需求集中，民族风刺绣服饰客单高；红蓝白通用素材可做挪威专属图案提高溢价。'),
(171,'犹太五旬节','Shavuot','2026-05-22',2026,'ME','犹太教三大节之一，纪念上帝在西奈山授予摩西十诫，节期两天。节日以白色为绝对主色，会堂与家中铺满鲜花绿叶——纪念大卫王与西奈花香，人们穿全白衣服参加彻夜诵经；餐桌上必吃奶酪蛋糕、千层面等乳制品，门框挂白色花环，窗户贴十诫主题贴纸，孩子收到带花饰的新 Torah 小卷轴礼物，社区举办奶制品烘焙大赛。','白色花艺装饰与乳制品烘焙周边是特色品类，与逾越节、光明节共享犹太市场客户；鲜花用品主推不易坏的仿真花。'),
(172,'犹太五旬节','Shavuot','2027-06-11',2027,'ME','犹太教三大节之一，纪念上帝在西奈山授予摩西十诫，节期两天。节日以白色为绝对主色，会堂与家中铺满鲜花绿叶——纪念大卫王与西奈花香，人们穿全白衣服参加彻夜诵经；餐桌上必吃奶酪蛋糕、千层面等乳制品，门框挂白色花环，窗户贴十诫主题贴纸，孩子收到带花饰的新 Torah 小卷轴礼物，社区举办奶制品烘焙大赛。','白色花艺装饰与乳制品烘焙周边是特色品类，与逾越节、光明节共享犹太市场客户；鲜花用品主推不易坏的仿真花。'),
(173,'圣克鲁桑节','Santacruzan / Flores de Mayo','2026-05-31',2026,'SEA','菲律宾5月鲜花月的收官盛典，融合天主教与民俗，纪念圣海伦娜寻获真十字架。月末大游行在黄昏开始，少女们身穿白色礼服扮演历代王后，最后一位“艾琳娜皇后”手捧十字架、头戴璀璨皇冠，伴随鲜花拱门与烛光行进；教堂整月以鲜花和棕榈装饰，节日色彩为象牙白、香槟金与玫瑰粉，女孩们戴着天使翅膀，沿街抛洒花瓣，散场后家庭共享 Halo-halo 刨冰。','皇冠、天使翅膀与鲜花头饰是少女刚需，白色礼服配饰客单高；与圣诞、复活节装扮品类共享供应链，主打菲律宾与海外菲佣市场。'),
(174,'圣克鲁桑节','Santacruzan / Flores de Mayo','2027-05-31',2027,'SEA','菲律宾5月鲜花月的收官盛典，融合天主教与民俗，纪念圣海伦娜寻获真十字架。月末大游行在黄昏开始，少女们身穿白色礼服扮演历代王后，最后一位“艾琳娜皇后”手捧十字架、头戴璀璨皇冠，伴随鲜花拱门与烛光行进；教堂整月以鲜花和棕榈装饰，节日色彩为象牙白、香槟金与玫瑰粉，女孩们戴着天使翅膀，沿街抛洒花瓣，散场后家庭共享 Halo-halo 刨冰。','皇冠、天使翅膀与鲜花头饰是少女刚需，白色礼服配饰客单高；与圣诞、复活节装扮品类共享供应链，主打菲律宾与海外菲佣市场。'),
(175,'意大利共和国日','Italian Republic Day (Festa della Repubblica)','2026-06-02',2026,'EU','纪念1946年公投废除君主制、建立共和国，意大利6月2日国庆。罗马帝国大道举行阅兵，总统向无名战士墓献花圈，三色箭飞行表演机尾喷出绿白红三色烟雾；节日主色为绿、白、红，街头挂满三色旗与三角旗，餐厅露台摆三色意面造型甜点，家庭在阳台悬挂国旗，傍晚广场有军乐演奏与烟花，博物馆免费开放。','绿白红三色品类与墨西哥/匈牙利等市场共享素材，加入意大利地图或比萨斜塔图案做区隔；国旗披风与脸彩在派对场景走量。'),
(176,'意大利共和国日','Italian Republic Day (Festa della Repubblica)','2027-06-02',2027,'EU','纪念1946年公投废除君主制、建立共和国，意大利6月2日国庆。罗马帝国大道举行阅兵，总统向无名战士墓献花圈，三色箭飞行表演机尾喷出绿白红三色烟雾；节日主色为绿、白、红，街头挂满三色旗与三角旗，餐厅露台摆三色意面造型甜点，家庭在阳台悬挂国旗，傍晚广场有军乐演奏与烟花，博物馆免费开放。','绿白红三色品类与墨西哥/匈牙利等市场共享素材，加入意大利地图或比萨斜塔图案做区隔；国旗披风与脸彩在派对场景走量。'),
(177,'菲律宾独立日','Philippine Independence Day','2026-06-12',2026,'SEA','纪念1898年脱离西班牙殖民、发表《独立宣言》。黎刹公园举行升旗与阅兵，节日色彩为国旗的蓝、红、白与太阳金；街头挂满红蓝彩旗与太阳光芒拉旗，学校组织民族服装日，学生穿 Barong Tagalog 刺绣礼服游行；家庭餐桌上摆 Adobo 烧鸡与 Halo-halo，海外菲侨社区同步游行，商场以三色气球拱门和金太阳装饰，晚间燃放烟火。','菲律宾一亿人口+海外侨民双市场，太阳光芒图案辨识度高；Barong 刺绣服装客单高，轻量装饰走跨境。'),
(178,'菲律宾独立日','Philippine Independence Day','2027-06-12',2027,'SEA','纪念1898年脱离西班牙殖民、发表《独立宣言》。黎刹公园举行升旗与阅兵，节日色彩为国旗的蓝、红、白与太阳金；街头挂满红蓝彩旗与太阳光芒拉旗，学校组织民族服装日，学生穿 Barong Tagalog 刺绣礼服游行；家庭餐桌上摆 Adobo 烧鸡与 Halo-halo，海外菲侨社区同步游行，商场以三色气球拱门和金太阳装饰，晚间燃放烟火。','菲律宾一亿人口+海外侨民双市场，太阳光芒图案辨识度高；Barong 刺绣服装客单高，轻量装饰走跨境。'),
(179,'俄罗斯日','Russia Day','2026-06-12',2026,'EU','俄罗斯联邦国庆，纪念1990年《国家主权宣言》通过。莫斯科红场举办大型音乐会与庆典，节日主色为白蓝红三色，克里姆林宫打出三色灯光；街头悬挂国旗与三色花环，公园举行亲子活动与民俗集市，人们穿印有国旗图案的T恤参加露天派对，家庭在阳台挂三色旗，晚间全国同步燃放烟花，年轻人流行戴三色发带。','三色品类与法国/荷兰等欧洲市场共享供应链，但要做俄语标识差异化；国旗T恤与腕带轻便好走量。'),
(180,'俄罗斯日','Russia Day','2027-06-12',2027,'EU','俄罗斯联邦国庆，纪念1990年《国家主权宣言》通过。莫斯科红场举办大型音乐会与庆典，节日主色为白蓝红三色，克里姆林宫打出三色灯光；街头悬挂国旗与三色花环，公园举行亲子活动与民俗集市，人们穿印有国旗图案的T恤参加露天派对，家庭在阳台挂三色旗，晚间全国同步燃放烟花，年轻人流行戴三色发带。','三色品类与法国/荷兰等欧洲市场共享供应链，但要做俄语标识差异化；国旗T恤与腕带轻便好走量。'),
(181,'美国国旗日','Flag Day (USA)','2026-06-14',2026,'NA','纪念1777年星条旗正式确立，虽非联邦假日但全美庆祝，也是美国陆军建军日。节日色彩就是红白蓝，居民区挂出国旗、门廊缠星条旗花环，学校要求穿星条元素服装并举行升旗；社区举行爱国游行与野餐，餐桌摆国旗餐盘与星条旗纸杯蛋糕，人们佩戴国旗徽章，傍晚在公园举行露天音乐会，童子军组织退役国旗焚烧礼。','夹在独立日备货周期内，可做一波补单；星条旗花环、门挂与餐盘为主推，与7月4日品类完全通用。'),
(182,'美国国旗日','Flag Day (USA)','2027-06-14',2027,'NA','纪念1777年星条旗正式确立，虽非联邦假日但全美庆祝，也是美国陆军建军日。节日色彩就是红白蓝，居民区挂出国旗、门廊缠星条旗花环，学校要求穿星条元素服装并举行升旗；社区举行爱国游行与野餐，餐桌摆国旗餐盘与星条旗纸杯蛋糕，人们佩戴国旗徽章，傍晚在公园举行露天音乐会，童子军组织退役国旗焚烧礼。','夹在独立日备货周期内，可做一波补单；星条旗花环、门挂与餐盘为主推，与7月4日品类完全通用。'),
(183,'北欧仲夏节','Midsummer','2026-06-19',2026,'EU','瑞典、芬兰、挪威、丹麦最重要的夏日庆典，在6月19至25日之间的星期五举行。人们到乡间竖起缠绕绿叶与鲜花的五月柱，围着它跳青蛙舞，节日色彩为草地绿、野花黄与天空蓝；女孩头戴自制野花环，穿白连衣裙配蓝丝带，餐桌摆腌鲱鱼、新土豆与草莓奶油蛋糕，大人痛饮调味烈酒，晚间点燃篝火，瑞典国旗蓝黄色彩点缀庭院。','野花环、五月柱DIY与白色连衣裙周边为刚需；花环材料包与蓝黄丝带走量，注意北欧消费者偏好天然材质。'),
(184,'北欧仲夏节','Midsummer','2027-06-25',2027,'EU','瑞典、芬兰、挪威、丹麦最重要的夏日庆典，在6月19至25日之间的星期五举行。人们到乡间竖起缠绕绿叶与鲜花的五月柱，围着它跳青蛙舞，节日色彩为草地绿、野花黄与天空蓝；女孩头戴自制野花环，穿白连衣裙配蓝丝带，餐桌摆腌鲱鱼、新土豆与草莓奶油蛋糕，大人痛饮调味烈酒，晚间点燃篝火，瑞典国旗蓝黄色彩点缀庭院。','野花环、五月柱DIY与白色连衣裙周边为刚需；花环材料包与蓝黄丝带走量，注意北欧消费者偏好天然材质。'),
(185,'骄傲月','Pride Month','2026-06-28',2026,'NA','每年6月为全球LGBTQ+骄傲月，月末周日举行大游行（纽约、旧金山、洛杉矶、伦敦同步），纪念石墙事件。节日色彩为六色彩虹，街道变成彩虹海洋：人们穿彩虹背带、亮片热裤、羽毛装饰参加游行，脸上涂彩虹色，沿街派发彩虹糖果与安全套；广场有露天演出和市集，酒吧举办变装秀，商场橱窗挂彩虹旗，家庭带孩子参加彩虹亲子跑，包装成“爱与平等”主题。','彩虹是全年通用元素、6月达到顶峰，轻量饰品与装扮品出单集中；设计走正能量包容路线，避免低俗化。'),
(186,'骄傲月','Pride Month','2027-06-27',2027,'NA','每年6月为全球LGBTQ+骄傲月，月末周日举行大游行（纽约、旧金山、洛杉矶、伦敦同步），纪念石墙事件。节日色彩为六色彩虹，街道变成彩虹海洋：人们穿彩虹背带、亮片热裤、羽毛装饰参加游行，脸上涂彩虹色，沿街派发彩虹糖果与安全套；广场有露天演出和市集，酒吧举办变装秀，商场橱窗挂彩虹旗，家庭带孩子参加彩虹亲子跑，包装成“爱与平等”主题。','彩虹是全年通用元素、6月达到顶峰，轻量饰品与装扮品出单集中；设计走正能量包容路线，避免低俗化。'),
(187,'圣费尔明奔牛节','San Fermín Festival','2026-07-06',2026,'EU','西班牙潘普洛纳年度盛事，7月6日正午市政厅礼花 Chupinazo 宣告开幕，持续至14日。每天清晨8点公牛沿石板小巷奔往斗牛场，穿全白衣裤、系红领巾红腰带的人群在公牛前奔跑，是全球最惊险的民俗；节日色彩为全白配圣费尔明红，广场摆满红酒袋，人们互洒红酒、高举报纸卷，阳台挂满红领巾，夜晚有烟花与街头乐队，脖子上挂的大蒜串与红方巾是标志装扮。','白色亚麻衣裤+红领巾红腰带套装是刚需，客单低但走量大；红酒袋与报纸卷造型道具为特色品类，主推西班牙游客。'),
(188,'圣费尔明奔牛节','San Fermín Festival','2027-07-06',2027,'EU','西班牙潘普洛纳年度盛事，7月6日正午市政厅礼花 Chupinazo 宣告开幕，持续至14日。每天清晨8点公牛沿石板小巷奔往斗牛场，穿全白衣裤、系红领巾红腰带的人群在公牛前奔跑，是全球最惊险的民俗；节日色彩为全白配圣费尔明红，广场摆满红酒袋，人们互洒红酒、高举报纸卷，阳台挂满红领巾，夜晚有烟花与街头乐队，脖子上挂的大蒜串与红方巾是标志装扮。','白色亚麻衣裤+红领巾红腰带套装是刚需，客单低但走量大；红酒袋与报纸卷造型道具为特色品类，主推西班牙游客。'),
(189,'那达慕大会','Naadam Festival','2026-07-11',2026,'ME','蒙古国“男儿三艺”国庆，7月11日至13日在全国举行，纪念1921年革命。乌兰巴托中央广场举行开幕阅兵与骑兵仪仗，节日色彩为草原蓝、奶白与鎏金；男子穿丝绸德勒长袍、系宽大绸腰带，摔跤手穿奇特的昭德格坎肩入场，弓箭手戴骨质扳指，儿童参加赛马；草原上搭起白色蒙古包，牧民煮整羊、熬奶茶招待宾客，姑娘戴银鎏金头饰，黄昏马头琴声伴着篝火。','草原民族风情品类与内蒙古市场相通，丝绸腰带、小弓玩具与银饰为主推；工艺品主推真正的民族纹样，客单可做高。'),
(190,'那达慕大会','Naadam Festival','2027-07-11',2027,'ME','蒙古国“男儿三艺”国庆，7月11日至13日在全国举行，纪念1921年革命。乌兰巴托中央广场举行开幕阅兵与骑兵仪仗，节日色彩为草原蓝、奶白与鎏金；男子穿丝绸德勒长袍、系宽大绸腰带，摔跤手穿奇特的昭德格坎肩入场，弓箭手戴骨质扳指，儿童参加赛马；草原上搭起白色蒙古包，牧民煮整羊、熬奶茶招待宾客，姑娘戴银鎏金头饰，黄昏马头琴声伴着篝火。','草原民族风情品类与内蒙古市场相通，丝绸腰带、小弓玩具与银饰为主推；工艺品主推真正的民族纹样，客单可做高。'),
(191,'法国巴士底日','Bastille Day (14 Juillet)','2026-07-14',2026,'EU','法国国庆，纪念1789年攻占巴士底狱。巴黎香榭丽舍大街举行世界最大阅兵，战机喷出蓝白红三色烟幕；节日色彩为蓝白红，街头咖啡馆挂满三色灯笼与三角旗，消防员举办舞会，消防对开放参观；家庭在阳台挂国旗，傍晚到战神广场野餐，夜间埃菲尔铁塔下燃放盛大烟火，年轻人戴三色贝雷帽、脸贴国旗贴纸，全城派对持续到凌晨。','蓝白红品类与多个欧洲市场通用，加入埃菲尔铁塔元素做法国专属溢价；贝雷帽、条纹衫等法式符号辨识度高。'),
(192,'法国巴士底日','Bastille Day (14 Juillet)','2027-07-14',2027,'EU','法国国庆，纪念1789年攻占巴士底狱。巴黎香榭丽舍大街举行世界最大阅兵，战机喷出蓝白红三色烟幕；节日色彩为蓝白红，街头咖啡馆挂满三色灯笼与三角旗，消防员举办舞会，消防对开放参观；家庭在阳台挂国旗，傍晚到战神广场野餐，夜间埃菲尔铁塔下燃放盛大烟火，年轻人戴三色贝雷帽、脸贴国旗贴纸，全城派对持续到凌晨。','蓝白红品类与多个欧洲市场通用，加入埃菲尔铁塔元素做法国专属溢价；贝雷帽、条纹衫等法式符号辨识度高。'),
(193,'哥伦比亚独立日','Colombian Independence Day','2026-07-20',2026,'LATAM','纪念1810年波哥大起义、迈向独立。波哥大举行阅兵与花车游行，节日色彩为国旗的黄、蓝、红，黄色占半幅最为醒目；街头挂满三色串旗与灯笼，人们戴黄蓝红假发与帽饰，孩子们穿三色校服参加学校游行；家庭餐桌上摆 Ajiaco 土豆鸡丝汤，酒吧供应朗姆鸡尾酒，晚间全城燃放烟火，广场有 Salsa 与 Vallenato 露天演唱会。','黄蓝红三色与委内瑞拉/厄瓜多尔配色接近，加入哥伦比亚帽元素做区隔；Agudelo草帽周边是特色品类。'),
(194,'哥伦比亚独立日','Colombian Independence Day','2027-07-20',2027,'LATAM','纪念1810年波哥大起义、迈向独立。波哥大举行阅兵与花车游行，节日色彩为国旗的黄、蓝、红，黄色占半幅最为醒目；街头挂满三色串旗与灯笼，人们戴黄蓝红假发与帽饰，孩子们穿三色校服参加学校游行；家庭餐桌上摆 Ajiaco 土豆鸡丝汤，酒吧供应朗姆鸡尾酒，晚间全城燃放烟火，广场有 Salsa 与 Vallenato 露天演唱会。','黄蓝红三色与委内瑞拉/厄瓜多尔配色接近，加入哥伦比亚帽元素做区隔；Agudelo草帽周边是特色品类。'),
(195,'秘鲁独立日','Peruvian Fiestas Patrias','2026-07-28',2026,'LATAM','秘鲁国庆连庆两天：7月28日纪念1821年独立，29日为陆军节。利马举行总统主持的 Te Deum 弥撒与盛大阅兵，节日色彩为国旗的红与白，街头挂满红白双色旗与彩带；人们戴红白绒球帽，家里摆羊驼玩偶与马丘比丘模型，餐桌供应烤全豚鼠、Ceviche 酸橘腌鱼与紫玉米汁，晚间海滨燃放烟火，广场有安第斯排箫与瓦伊诺舞表演。','红白配色与周边多国共享，羊驼、马丘比丘等秘鲁符号辨识度高；羊驼毛绒制品与民族风饰品客单可观。'),
(196,'秘鲁独立日','Peruvian Fiestas Patrias','2027-07-28',2027,'LATAM','秘鲁国庆连庆两天：7月28日纪念1821年独立，29日为陆军节。利马举行总统主持的 Te Deum 弥撒与盛大阅兵，节日色彩为国旗的红与白，街头挂满红白双色旗与彩带；人们戴红白绒球帽，家里摆羊驼玩偶与马丘比丘模型，餐桌供应烤全豚鼠、Ceviche 酸橘腌鱼与紫玉米汁，晚间海滨燃放烟火，广场有安第斯排箫与瓦伊诺舞表演。','红白配色与周边多国共享，羊驼、马丘比丘等秘鲁符号辨识度高；羊驼毛绒制品与民族风饰品客单可观。'),
(197,'瑞士国庆日','Swiss National Day','2026-08-01',2026,'EU','纪念1291年联邦永久同盟宪章，8月1日是瑞士国庆。节日色彩为国旗的红与白十字，阿尔卑斯山村在山顶点燃篝火，家家户户悬挂红底白十字国旗；人们穿传统服饰参加牛铃游行与合唱，面包师烤瑞士十字面包，农场举办早午餐，儿童提着纸灯笼夜游，湖边城镇燃放烟火倒映湖面，城镇广场分发免费登山早餐。','红底白十字品类辨识度高，牛铃、纸灯笼与十字面包是特色；阿尔卑斯主题产品可与德国/奥地利南部市场共享。'),
(198,'瑞士国庆日','Swiss National Day','2027-08-01',2027,'EU','纪念1291年联邦永久同盟宪章，8月1日是瑞士国庆。节日色彩为国旗的红与白十字，阿尔卑斯山村在山顶点燃篝火，家家户户悬挂红底白十字国旗；人们穿传统服饰参加牛铃游行与合唱，面包师烤瑞士十字面包，农场举办早午餐，儿童提着纸灯笼夜游，湖边城镇燃放烟火倒映湖面，城镇广场分发免费登山早餐。','红底白十字品类辨识度高，牛铃、纸灯笼与十字面包是特色；阿尔卑斯主题产品可与德国/奥地利南部市场共享。'),
(199,'巴基斯坦独立日','Pakistan Independence Day','2026-08-14',2026,'ME','纪念1947年8月14日巴基斯坦独立（比印度早一天）。节日主色为深绿与白，伊斯兰堡总统府举行升旗仪式，全国奏响 21 响礼炮；街头车辆挂满绿白旗与星月灯串，孩子们穿绿白衣服、戴星月发夹，脸涂绿色参加学校庆典，商场与地标打出绿色灯光秀，年轻人骑着装饰彩旗的摩托巡游，晚间各地燃放烟火。','与3月巴基斯坦日共享品类，绿白星月供应链全年通用；脸彩、车旗与发光饰品在节前一周走量。'),
(200,'巴基斯坦独立日','Pakistan Independence Day','2027-08-14',2027,'ME','纪念1947年8月14日巴基斯坦独立（比印度早一天）。节日主色为深绿与白，伊斯兰堡总统府举行升旗仪式，全国奏响 21 响礼炮；街头车辆挂满绿白旗与星月灯串，孩子们穿绿白衣服、戴星月发夹，脸涂绿色参加学校庆典，商场与地标打出绿色灯光秀，年轻人骑着装饰彩旗的摩托巡游，晚间各地燃放烟火。','与3月巴基斯坦日共享品类，绿白星月供应链全年通用；脸彩、车旗与发光饰品在节前一周走量。'),
(201,'乌克兰独立日','Ukrainian Independence Day','2026-08-24',2026,'EU','纪念1991年脱离苏联独立，8月24日是乌克兰最重要的国庆。基辅赫雷夏蒂克大街举行阅兵与装备展，节日主色为国旗的上蓝下黄，街道张挂蓝黄双色旗；人们佩戴蓝黄缎带与向日葵胸花，女青年编织花冠，民间歌手在广场演唱，住宅楼阳台挂满国旗，家庭餐桌上摆蓝黄配色蛋糕，傍晚全国为逝者默哀后燃放烟火。','蓝黄配色品类辨识度极高，向日葵与刺绣 Vyshyvanka 纹样是民族符号；社会情绪复杂，设计庄重、突出和平与爱国主题。'),
(202,'乌克兰独立日','Ukrainian Independence Day','2027-08-24',2027,'EU','纪念1991年脱离苏联独立，8月24日是乌克兰最重要的国庆。基辅赫雷夏蒂克大街举行阅兵与装备展，节日主色为国旗的上蓝下黄，街道张挂蓝黄双色旗；人们佩戴蓝黄缎带与向日葵胸花，女青年编织花冠，民间歌手在广场演唱，住宅楼阳台挂满国旗，家庭餐桌上摆蓝黄配色蛋糕，傍晚全国为逝者默哀后燃放烟火。','蓝黄配色品类辨识度极高，向日葵与刺绣 Vyshyvanka 纹样是民族符号；社会情绪复杂，设计庄重、突出和平与爱国主题。'),
(203,'番茄大战','La Tomatina','2026-08-26',2026,'EU','西班牙布尼奥尔小镇每年8月最后一个星期三的“世界最大食物大战”，上午11点卡车载着15吨熟番茄驶入广场，信号一响两万游客互相投掷番茄，全城化为红色番茄河；战前先有火腿杆攀爬热身，战后人们用街边水管互相冲洗，节日色彩为番茄红、酸橙绿与明黄，游客穿旧白T恤戴护目镜，酒吧供应 Sangría 与番茄面包。','参战周边以防护与清洁用品为特色：护目镜、防水袋、白T恤套装；游客刚需且轻便，节前一周在西班牙站冲刺。'),
(204,'番茄大战','La Tomatina','2027-08-25',2027,'EU','西班牙布尼奥尔小镇每年8月最后一个星期三的“世界最大食物大战”，上午11点卡车载着15吨熟番茄驶入广场，信号一响两万游客互相投掷番茄，全城化为红色番茄河；战前先有火腿杆攀爬热身，战后人们用街边水管互相冲洗，节日色彩为番茄红、酸橙绿与明黄，游客穿旧白T恤戴护目镜，酒吧供应 Sangría 与番茄面包。','参战周边以防护与清洁用品为特色：护目镜、防水袋、白T恤套装；游客刚需且轻便，节前一周在西班牙站冲刺。'),
(205,'火人节','Burning Man','2026-08-30',2026,'NA','美国内华达黑石沙漠的反传统狂欢，每年劳工节前的周日开幕、持续8天，最后一夜焚烧巨型木人。节日没有官方色彩，但荧光色、金属色与沙漠裸色系是主流：人们穿皮草大衣配荧光腿套、护目镜防尘，营地布满 LED 发光雕塑与艺术车；白天参加瑜伽与 DJ 派对，夜晚骑车挂满彩灯穿梭，人们互赠“礼物经济”手工，灰烬散去后不留一片垃圾。','节日穿搭是 TikTok 爆款话题：护目镜、发光配饰、沙漠靴与皮草大衣周边需求集中；设计越夸张越好卖，提前60天上架。'),
(206,'火人节','Burning Man','2027-08-29',2027,'NA','美国内华达黑石沙漠的反传统狂欢，每年劳工节前的周日开幕、持续8天，最后一夜焚烧巨型木人。节日没有官方色彩，但荧光色、金属色与沙漠裸色系是主流：人们穿皮草大衣配荧光腿套、护目镜防尘，营地布满 LED 发光雕塑与艺术车；白天参加瑜伽与 DJ 派对，夜晚骑车挂满彩灯穿梭，人们互赠“礼物经济”手工，灰烬散去后不留一片垃圾。','节日穿搭是 TikTok 爆款话题：护目镜、发光配饰、沙漠靴与皮草大衣周边需求集中；设计越夸张越好卖，提前60天上架。'),
(207,'犹太新年','Rosh Hashanah','2026-09-12',2026,'ME','犹太教岁首，为期两天，纪念创世，随后十天忏悔直到赎罪日。节日色彩为白、金、深紫与石榴红，会堂吹响羊角号 Shofar；晚餐餐桌上摆蘸蜜的苹果片、石榴、圆形 Challah 辫子面包，寓意甜蜜新年；人们穿白色新衣，家中挂“Shanah Tovah”金色拉旗，给亲友寄送新年贺卡，餐桌中央摆蜂蜜罐与蜂巢装饰，鱼头等吉祥菜不可少。','羊角号、蜂蜜餐具与石榴周边是节日特色，金色系装饰与光明节供应链通用；面向以色列与北美犹太社区提前45天备货。'),
(208,'犹太新年','Rosh Hashanah','2027-10-02',2027,'ME','犹太教岁首，为期两天，纪念创世，随后十天忏悔直到赎罪日。节日色彩为白、金、深紫与石榴红，会堂吹响羊角号 Shofar；晚餐餐桌上摆蘸蜜的苹果片、石榴、圆形 Challah 辫子面包，寓意甜蜜新年；人们穿白色新衣，家中挂“Shanah Tovah”金色拉旗，给亲友寄送新年贺卡，餐桌中央摆蜂蜜罐与蜂巢装饰，鱼头等吉祥菜不可少。','羊角号、蜂蜜餐具与石榴周边是节日特色，金色系装饰与光明节供应链通用；面向以色列与北美犹太社区提前45天备货。'),
(209,'马来西亚日','Malaysia Day (Hari Malaysia)','2026-09-16',2026,'SEA','纪念1963年马来亚、沙巴、砂拉越与新加坡组成马来西亚联邦（新加坡后来退出），9月16日是全国公共假日。吉隆坡举行盛大游行与文艺演出，节日色彩丰富，以辉煌条纹旗的蓝、黄、红、白为主；街头挂起红白条纹旗与各族旗帜，学生手持小旗游行，商场布置多元民族主题展，家庭团聚吃椰浆饭与肉骨茶，东马沙巴砂拉越还有达雅族传统舞蹈。','与8月底国庆（独立日）相距半月、形成二次备货；国旗条纹元素与多元民族服饰为主推，主打东马本地仓。'),
(210,'马来西亚日','Malaysia Day (Hari Malaysia)','2027-09-16',2027,'SEA','纪念1963年马来亚、沙巴、砂拉越与新加坡组成马来西亚联邦（新加坡后来退出），9月16日是全国公共假日。吉隆坡举行盛大游行与文艺演出，节日色彩丰富，以辉煌条纹旗的蓝、黄、红、白为主；街头挂起红白条纹旗与各族旗帜，学生手持小旗游行，商场布置多元民族主题展，家庭团聚吃椰浆饭与肉骨茶，东马沙巴砂拉越还有达雅族传统舞蹈。','与8月底国庆（独立日）相距半月、形成二次备货；国旗条纹元素与多元民族服饰为主推，主打东马本地仓。'),
(211,'住棚节','Sukkot (Feast of Tabernacles)','2026-09-26',2026,'ME','犹太教三大朝圣节之一，纪念出埃及时在旷野住棚，节期7天（以色列）至8天（海外）。人们在庭院或阳台搭建 Sukkah 棚舍，以木架布围、屋顶铺修剪过的树枝，可看见星空；全家在棚下吃饭待客，节日色彩为橄榄绿、丰收橙、金色与深紫，棚内挂水果串与丰收装饰，男士手持 Lulav 棕榈枝束与 Etrog 香柠檬做祈祷，末日后紧接着诵经节 Simchat Torah 欢舞。','棚舍搭建材料与丰收装饰是节日刚需，水果挂串、棕榈枝周边为特色品类；大件棚架走本地仓，装饰小物走跨境。'),
(212,'住棚节','Sukkot (Feast of Tabernacles)','2027-10-16',2027,'ME','犹太教三大朝圣节之一，纪念出埃及时在旷野住棚，节期7天（以色列）至8天（海外）。人们在庭院或阳台搭建 Sukkah 棚舍，以木架布围、屋顶铺修剪过的树枝，可看见星空；全家在棚下吃饭待客，节日色彩为橄榄绿、丰收橙、金色与深紫，棚内挂水果串与丰收装饰，男士手持 Lulav 棕榈枝束与 Etrog 香柠檬做祈祷，末日后紧接着诵经节 Simchat Torah 欢舞。','棚舍搭建材料与丰收装饰是节日刚需，水果挂串、棕榈枝周边为特色品类；大件棚架走本地仓，装饰小物走跨境。'),
(213,'德国统一日','German Unity Day (Tag der Deutschen Einheit)','2026-10-03',2026,'EU','纪念1990年10月3日东西德统一，是德国现代国庆。庆祝城市每年轮换主办，举行联邦各州庆典博览会与总统招待会，节日色彩为黑、红、金三色；街头悬挂三色旗，柏林勃兰登堡门举办露天市民节，人们穿日常装手持小旗，面包师烤黑红金三色蛋糕，广场有摇滚乐队演出与脱口秀，各党派发放气球与旗帜，晚间在施普雷河畔放烟火。','黑红金三色品类与比利时/埃及等市场配色相近，加入勃兰登堡门或联邦鹰元素做区隔；客单轻松日常为主。'),
(214,'德国统一日','German Unity Day (Tag der Deutschen Einheit)','2027-10-03',2027,'EU','纪念1990年10月3日东西德统一，是德国现代国庆。庆祝城市每年轮换主办，举行联邦各州庆典博览会与总统招待会，节日色彩为黑、红、金三色；街头悬挂三色旗，柏林勃兰登堡门举办露天市民节，人们穿日常装手持小旗，面包师烤黑红金三色蛋糕，广场有摇滚乐队演出与脱口秀，各党派发放气球与旗帜，晚间在施普雷河畔放烟火。','黑红金三色品类与比利时/埃及等市场配色相近，加入勃兰登堡门或联邦鹰元素做区隔；客单轻松日常为主。'),
(215,'西班牙国庆','Spain National Day (Fiesta Nacional / Día de la Hispanidad)','2026-10-12',2026,'EU','10月12日西班牙国庆，纪念1492年哥伦布抵达美洲，也纪念西班牙语世界同源。马德里阅兵由国王主持，三军仪仗与战机拉着红黄两色烟带通过；节日色彩为国旗的红与黄，街头悬挂红黄双色旗与国徽旗，马德里王宫升起巨型国旗，人们佩戴红黄腕带，酒吧供应海鲜饭与桑格利亚，海外拉美裔社区也共同庆祝“西语日”，晚间广场有弗拉门戈演出。','红黄色品类与拉美市场供应链相通，加入斗牛士、吉他等符号做西班牙特色；轻便饰品与国旗T恤走量。'),
(216,'西班牙国庆','Spain National Day (Fiesta Nacional / Día de la Hispanidad)','2027-10-12',2027,'EU','10月12日西班牙国庆，纪念1492年哥伦布抵达美洲，也纪念西班牙语世界同源。马德里阅兵由国王主持，三军仪仗与战机拉着红黄两色烟带通过；节日色彩为国旗的红与黄，街头悬挂红黄双色旗与国徽旗，马德里王宫升起巨型国旗，人们佩戴红黄腕带，酒吧供应海鲜饭与桑格利亚，海外拉美裔社区也共同庆祝“西语日”，晚间广场有弗拉门戈演出。','红黄色品类与拉美市场供应链相通，加入斗牛士、吉他等符号做西班牙特色；轻便饰品与国旗T恤走量。'),
(217,'土耳其共和国日','Turkey Republic Day (29 Ekim)','2026-10-29',2026,'ME','纪念1923年10月29日土耳其共和国宣告成立、国父凯末尔就任首任总统。安卡拉阿尼特卡比尔陵寝举行献花仪式，伊斯坦布尔博斯普鲁斯海峡两岸举行盛大烟火与无人机灯光秀；节日色彩为国旗的红与白，街头与阳台上红旗招展，人们在脸上画星月、举火炬游行，孩子们朗诵 Atatürk 诗歌，家庭餐桌摆烤肉与 Baklava 果仁蜜饼，晚间轮船鸣汽笛庆祝。','红白星月品类与多个穆斯林市场通用，但加入凯末尔签名/语录元素是土耳其专属；国旗大件走本地仓，脸彩小物走跨境。'),
(218,'土耳其共和国日','Turkey Republic Day (29 Ekim)','2027-10-29',2027,'ME','纪念1923年10月29日土耳其共和国宣告成立、国父凯末尔就任首任总统。安卡拉阿尼特卡比尔陵寝举行献花仪式，伊斯坦布尔博斯普鲁斯海峡两岸举行盛大烟火与无人机灯光秀；节日色彩为国旗的红与白，街头与阳台上红旗招展，人们在脸上画星月、举火炬游行，孩子们朗诵 Atatürk 诗歌，家庭餐桌摆烤肉与 Baklava 果仁蜜饼，晚间轮船鸣汽笛庆祝。','红白星月品类与多个穆斯林市场通用，但加入凯末尔签名/语录元素是土耳其专属；国旗大件走本地仓，脸彩小物走跨境。'),
(219,'诸圣节','All Saints’ Day (Toussaint)','2026-11-01',2026,'EU','天主教与圣公会纪念所有圣徒的节日，11月1日在法国、意大利、波兰、西班牙等国是公共假日，次日2日为追思已亡节。节日色彩肃穆，以白、深紫与菊花黄为主，全家携带白菊花束与长明墓前灯祭扫公墓，擦拭墓碑、点燃玻璃防风蜡烛；教堂举行追思弥撒、钟楼长鸣，家中摆圣徒像与白色蜡烛，餐桌只上简朴的炖菜，商店菊花专柜前人流如织。','与万圣节娱乐主题完全不同：墓前防风蜡烛、仿真白菊花为刚需；玻璃电子蜡烛安全款在欧洲城市公墓接受度高。'),
(220,'诸圣节','All Saints’ Day (Toussaint)','2027-11-01',2027,'EU','天主教与圣公会纪念所有圣徒的节日，11月1日在法国、意大利、波兰、西班牙等国是公共假日，次日2日为追思已亡节。节日色彩肃穆，以白、深紫与菊花黄为主，全家携带白菊花束与长明墓前灯祭扫公墓，擦拭墓碑、点燃玻璃防风蜡烛；教堂举行追思弥撒、钟楼长鸣，家中摆圣徒像与白色蜡烛，餐桌只上简朴的炖菜，商店菊花专柜前人流如织。','与万圣节娱乐主题完全不同：墓前防风蜡烛、仿真白菊花为刚需；玻璃电子蜡烛安全款在欧洲城市公墓接受度高。'),
(221,'墨西哥革命纪念日','Mexican Revolution Day','2026-11-16',2026,'LATAM','纪念1910年墨西哥革命爆发，官方庆典定在11月第三个星期一（原为11月20日）。墨西哥城改革大道举行盛大阅兵与骑兵游行，节日色彩为国旗的绿、白、红，街头悬挂三色旗；孩子们戴 Pancho Villa 式宽边帽、贴小胡子参加学校历史剧，社区举办革命主题展览，家庭餐桌摆 Mole 酱鸡与玉米粽，广场有 Mariachi 街头乐队与民俗舞表演，晚间燃放烟火。','爱国主题品类与9月独立日通用，宽边帽、小胡子等装扮道具在儿童市场走量；节后可衔接亡灵节余温做联动营销。'),
(222,'墨西哥革命纪念日','Mexican Revolution Day','2027-11-15',2027,'LATAM','纪念1910年墨西哥革命爆发，官方庆典定在11月第三个星期一（原为11月20日）。墨西哥城改革大道举行盛大阅兵与骑兵游行，节日色彩为国旗的绿、白、红，街头悬挂三色旗；孩子们戴 Pancho Villa 式宽边帽、贴小胡子参加学校历史剧，社区举办革命主题展览，家庭餐桌摆 Mole 酱鸡与玉米粽，广场有 Mariachi 街头乐队与民俗舞表演，晚间燃放烟火。','爱国主题品类与9月独立日通用，宽边帽、小胡子等装扮道具在儿童市场走量；节后可衔接亡灵节余温做联动营销。'),
(223,'阿曼国庆','Oman National Day','2026-11-18',2026,'ME','阿曼苏丹国国庆，庆祝卡布斯苏丹开创现代阿曼，11月18日起连庆两天。马斯喀特大街小巷张灯结彩，以国旗的红、白、绿三色与苏丹徽章为主题，政府大楼灯光秀彻夜通明；人们穿传统白色 Dishdasha 长袍、佩戴 Khanjar 弯刃匕首参加游行，骆驼与马队披红挂彩，商场举办民俗展，家庭在沙漠营地野餐，晚间海湾上空燃放烟火，孩子们挥舞小旗。','海湾高客单市场，Khanjar匕首造型饰品与红白绿装饰为特色；竞争卖家少，适合提前布局做差异化。'),
(224,'阿曼国庆','Oman National Day','2027-11-18',2027,'ME','阿曼苏丹国国庆，庆祝卡布斯苏丹开创现代阿曼，11月18日起连庆两天。马斯喀特大街小巷张灯结彩，以国旗的红、白、绿三色与苏丹徽章为主题，政府大楼灯光秀彻夜通明；人们穿传统白色 Dishdasha 长袍、佩戴 Khanjar 弯刃匕首参加游行，骆驼与马队披红挂彩，商场举办民俗展，家庭在沙漠营地野餐，晚间海湾上空燃放烟火，孩子们挥舞小旗。','海湾高客单市场，Khanjar匕首造型饰品与红白绿装饰为特色；竞争卖家少，适合提前布局做差异化。'),
(225,'巴西黑人意识日','Black Consciousness Day (Consciência Negra)','2026-11-20',2026,'LATAM','巴西纪念非裔文化与 Zumbi dos Palmares 反抗奴隶制的纪念日，11月20日在圣保罗、里约等州为公共假日。节日色彩以非洲风情的绿、黄、红、黑为主，萨尔瓦多与里约举行 Samba 鼓乐巡游与 Capoeira 武术表演；人们穿非洲印花蜡染衫、戴头巾珠饰，学校开设非裔历史课，社区供应 Feijoada 黑豆炖肉，广场有 Candomblé 宗教仪式与集市，青年举“黑人生命重要”标语游行。','非裔文化主题小众但竞争小，非洲印花服饰、头巾与鼓类乐器为主推；设计尊重文化根源，避免刻板元素。'),
(226,'巴西黑人意识日','Black Consciousness Day (Consciência Negra)','2027-11-20',2027,'LATAM','巴西纪念非裔文化与 Zumbi dos Palmares 反抗奴隶制的纪念日，11月20日在圣保罗、里约等州为公共假日。节日色彩以非洲风情的绿、黄、红、黑为主，萨尔瓦多与里约举行 Samba 鼓乐巡游与 Capoeira 武术表演；人们穿非洲印花蜡染衫、戴头巾珠饰，学校开设非裔历史课，社区供应 Feijoada 黑豆炖肉，广场有 Candomblé 宗教仪式与集市，青年举“黑人生命重要”标语游行。','非裔文化主题小众但竞争小，非洲印花服饰、头巾与鼓类乐器为主推；设计尊重文化根源，避免刻板元素。'),
(227,'光明节','Hanukkah (Chanukah)','2026-12-05',2026,'ME','犹太修殿节，纪念马卡比起义后圣殿油灯奇迹（仅够一天的油燃了八天），连续庆祝八夜，每夜多点一支蜡烛，第九支 Shamash 用来引火。节日色彩为蓝、白、金，家中摆放九枝烛台 Hanukkiah，全家围坐吃土豆 Latke 饼与果酱 Sufganiyot 甜甜圈；孩子们玩旋转陀螺 Dreidel、收巧克力金币礼物，门窗挂蓝色串灯，客厅摆烛台造型抱枕，亲友来家参加点灯派对。','九枝烛台、陀螺与巧克力金币网袋是节日刚需，蓝白金品类与其他犹太节共享；蜡烛安全款与电子烛台更受有孩家庭欢迎。'),
(228,'光明节','Hanukkah (Chanukah)','2027-12-25',2027,'ME','犹太修殿节，纪念马卡比起义后圣殿油灯奇迹（仅够一天的油燃了八天），连续庆祝八夜，每夜多点一支蜡烛，第九支 Shamash 用来引火。节日色彩为蓝、白、金，家中摆放九枝烛台 Hanukkiah，全家围坐吃土豆 Latke 饼与果酱 Sufganiyot 甜甜圈；孩子们玩旋转陀螺 Dreidel、收巧克力金币礼物，门窗挂蓝色串灯，客厅摆烛台造型抱枕，亲友来家参加点灯派对。','九枝烛台、陀螺与巧克力金币网袋是节日刚需，蓝白金品类与其他犹太节共享；蜡烛安全款与电子烛台更受有孩家庭欢迎。'),
(229,'圣露西亚节','Saint Lucy’s Day (Lucia)','2026-12-13',2026,'EU','北欧黑暗冬季的烛光节日，纪念三世纪殉道圣女露西亚，12月13日在瑞典、挪威、芬兰、丹麦庆祝。清晨家中女孩扮成 Lucia：穿白色长袍、腰间系红丝带、头戴插着蜡烛的绿叶冠，手捧藏红花面包 Singing 走进父母卧室；节日色彩为白、烛光金与圣诞红，学校与教堂举行 Lucia 唱诗游行，咖啡馆供应藏红花小面包与热红酒，烛冠与纸灯笼照亮漫长冬夜。','烛冠头饰与白袍红丝带套装是儿童刚需，藏红花面包模具与烛光装饰为主推；与圣诞季供应链完全通用。'),
(230,'圣露西亚节','Saint Lucy’s Day (Lucia)','2027-12-13',2027,'EU','北欧黑暗冬季的烛光节日，纪念三世纪殉道圣女露西亚，12月13日在瑞典、挪威、芬兰、丹麦庆祝。清晨家中女孩扮成 Lucia：穿白色长袍、腰间系红丝带、头戴插着蜡烛的绿叶冠，手捧藏红花面包 Singing 走进父母卧室；节日色彩为白、烛光金与圣诞红，学校与教堂举行 Lucia 唱诗游行，咖啡馆供应藏红花小面包与热红酒，烛冠与纸灯笼照亮漫长冬夜。','烛冠头饰与白袍红丝带套装是儿童刚需，藏红花面包模具与烛光装饰为主推；与圣诞季供应链完全通用。'),
(231,'卡塔尔国庆','Qatar National Day','2026-12-18',2026,'ME','卡塔尔国庆纪念1878年贾西姆·本·穆罕默德·阿勒萨尼统一半岛建国，12月18日多哈全城大庆。节日主色为栗色（国旗独有色）与白，滨海大道举行阅兵、传统骆驼马队游行与 Dhau 帆船表演；街头悬挂栗白双色国旗与 Sword 弯刀徽章，人们穿栗色服饰，儿童画脸，独桅帆船张灯，晚间有盛大烟火与无人机表演，家庭在沙漠帐篷里喝咖啡、吃 Machbous 香料饭。','栗白配色在全球国旗中独一无二、极易做出辨识度；弯刀徽章、独桅帆船造型饰品为特色，海湾客单高。'),
(232,'卡塔尔国庆','Qatar National Day','2027-12-18',2027,'ME','卡塔尔国庆纪念1878年贾西姆·本·穆罕默德·阿勒萨尼统一半岛建国，12月18日多哈全城大庆。节日主色为栗色（国旗独有色）与白，滨海大道举行阅兵、传统骆驼马队游行与 Dhau 帆船表演；街头悬挂栗白双色国旗与 Sword 弯刀徽章，人们穿栗色服饰，儿童画脸，独桅帆船张灯，晚间有盛大烟火与无人机表演，家庭在沙漠帐篷里喝咖啡、吃 Machbous 香料饭。','栗白配色在全球国旗中独一无二、极易做出辨识度；弯刀徽章、独桅帆船造型饰品为特色，海湾客单高。'),
(233,'宽扎节','Kwanzaa','2026-12-26',2026,'NA','非裔美国人的文化节日，12月26日至1月1日连庆七天，纪念非洲传统与家庭价值，每天点燃 Kinara 七枝烛台中的一支（三支红、三支绿、中间黑烛）。节日色彩为红、黑、绿，家中铺 Mkeka 草编席，摆 Mazao 果盘、Unity Cup 团结杯与玉米穗；全家轮流讲七项原则（团结、自决、集体劳动等），互换手工礼物，最后夜 Karamu 非洲盛宴，鼓声与舞会通宵。','文化属性强、用户忠诚度高，Kinara烛台、Mkeka草席与七原则挂画是刚需；竞争远小于圣诞，适合做长期长青链接。'),
(234,'宽扎节','Kwanzaa','2027-12-26',2027,'NA','非裔美国人的文化节日，12月26日至1月1日连庆七天，纪念非洲传统与家庭价值，每天点燃 Kinara 七枝烛台中的一支（三支红、三支绿、中间黑烛）。节日色彩为红、黑、绿，家中铺 Mkeka 草编席，摆 Mazao 果盘、Unity Cup 团结杯与玉米穗；全家轮流讲七项原则（团结、自决、集体劳动等），互换手工礼物，最后夜 Karamu 非洲盛宴，鼓声与舞会通宵。','文化属性强、用户忠诚度高，Kinara烛台、Mkeka草席与七原则挂画是刚需；竞争远小于圣诞，适合做长期长青链接。');

